insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','GNL Wind Service A/S','new','A','Дания','Roslev','fwj@gnlservice.dk','https://gnlservice.dk','Flemming W. Jensen (технический планировщик и закупки)','Сервис, ремонт и retrofit ветряков по всей Дании, продают запчасти.','{"rank": 1, "fit_score": 10, "why": "Сами занимаются сервисом и запчастями, а значит постоянно сталкиваются с мелочью, которую долго ждать у производителя. Человек, которому пишем, отвечает за закупки.", "give": "Мелкие пластиковые детали и запчасти под их сервис: крышки, втулки, кронштейны, клипсы малыми партиями.", "lang": "da", "subject_da": "Små plastdele til vindmølleservice", "body_da": "Hej Flemming,\nJeg kan se, at I servicerer og renoverer vindmøller og sælger reservedele. Vi skaffer og får fremstillet mindre plastdele, f.eks. dæksler, bøsninger, beslag og clips. Det kan være noget, der er svært at få fra producenten, eller som tager for lang tid at få hjem. Har I en sådan del, må I gerne sende et billede eller en kort beskrivelse. Så ser vi på den og vender tilbage med et konkret forslag, hvis vi kan løse den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие пластиковые детали для сервиса ветряков", "body_ru": "Здравствуйте, Флемминг,\nЯ вижу, что вы обслуживаете и ремонтируете ветряки и продаёте запчасти. Мы подбираем и заказываем изготовление небольших пластиковых деталей, например крышек, втулок, кронштейнов и клипс. Это может быть то, что трудно получить от производителя или что слишком долго ждать. Если у вас есть такая деталь, пришлите, пожалуйста, фото или короткое описание. Мы посмотрим и вернёмся с конкретным предложением, если сможем решить задачу.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','PJT Vindmølleservice (Per & Jørgen Therkildsen A/S)','new','A','Дания','Østervrå','service@pjtservice.dk','https://pjtservice.dk','','Региональный сервис ветряков с собственным складом запчастей для старых моделей.','{"rank": 2, "fit_score": 10, "why": "Держат склад под Micon, NEG Micon, Vestas и Wind World, а редкие детали берут у субподрядчиков. Это ровно наша ниша.", "give": "Быстро подобрать или сделать редкую мелкую деталь, которой нет на их складе.", "lang": "da", "subject_da": "Sjældne dele til ældre møller", "body_da": "Hej,\nJeg så, at I har reservedele til ældre møller som Micon, NEG Micon, Vestas og Wind World. Hvis der er en lille plastdel, som I ikke har på lager, kan vi måske hjælpe. Vi skaffer og får fremstillet bl.a. bøsninger, dæksler og beslag, også i få styk. Send gerne et billede af delen eller selve delen, så kigger vi på den. Hvis det kan lade sig gøre, får I et konkret forslag fra os.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Редкие детали для старых ветряков", "body_ru": "Здравствуйте,\nЯ увидел, что у вас есть запчасти для старых турбин, таких как Micon, NEG Micon, Vestas и Wind World. Если есть небольшая пластиковая деталь, которой нет у вас на складе, возможно, мы сможем помочь. Мы подбираем и заказываем изготовление, в частности, втулок, крышек и кронштейнов, в том числе в единичных экземплярах. Пришлите фото детали или саму деталь, мы её посмотрим. Если это возможно, вы получите от нас конкретное предложение.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Momentum Energy Services A/S','new','A','Дания','Balle','mes@momentumgreenenergy.com','https://momentumenergyservices.dk','','Национальный сервис ветряков и солнечных парков, 17+ сервисных машин.','{"rank": 3, "fit_score": 9, "why": "Много сервисных бригад, которым нужны расходные мелочи прямо в машине, без долгого ожидания.", "give": "Регулярная поставка мелких деталей для сервиса: клипсы, колпачки, крышки, кронштейны.", "lang": "da", "subject_da": "Småt til servicebilerne", "body_da": "Hej,\nVi er et lille firma, der hjælper med små plastdele og reservedele i mindre mængder. Jeg har set, at I laver service på vind- og solparker med mange servicebiler på vejen. Det kan være clips, hætter, dæksler eller beslag, som er besværlige at få fat i, når man kun skal bruge nogle få. Har I en konkret del i tankerne, så send os et billede.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелочи для сервисных машин", "body_ru": "Здравствуйте,\nМы небольшая фирма, которая помогает с мелкими пластиковыми деталями и запчастями в небольших количествах. Я посмотрел, что вы обслуживаете ветряные и солнечные парки, и у вас много сервисных машин. Это могут быть клипсы, колпачки, крышки или кронштейны, которые трудно достать, когда нужно всего несколько штук. Если у вас есть конкретная деталь, пришлите нам фото.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Wincon A/S','new','A','Дания','Randers','service@wincon.dk','https://wincon.dk','','Один из старейших независимых сервисов ветряков в Дании, ремонт и реновация.','{"rank": 4, "fit_score": 9, "why": "Работают со старыми турбинами, где пластиковые детали часто сняты с производства или идут очень долго.", "give": "Замена снятых с производства крышек, втулок и других мелких деталей по образцу или фото.", "lang": "da", "subject_da": "Plastdele til ældre vindmøller", "body_da": "Hej,\nDa I renoverer ældre vindmøller, kender I sikkert problemet: En lille plastdel er udgået, og originalen tager en evighed at få. Vi hjælper med at skaffe eller få lavet dæksler, bøsninger og lignende i små mængder, ofte ud fra en prøve eller et billede. Har I en del, I gerne vil have set på, må I sende den eller et foto. Så skriver vi tilbage, hvis vi kan klare den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых ветряков", "body_ru": "Здравствуйте,\nРаз вы ремонтируете старые ветряки, вы наверняка знакомы с проблемой: маленькая пластиковая деталь снята с производства, а оригинал ждать целую вечность. Мы помогаем найти или изготовить крышки, втулки и подобные детали в небольших количествах, часто по образцу или по фото. Если есть деталь, которую вы хотели бы показать, пришлите её или фото. Мы напишем в ответ, если сможем с ней справиться.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Windturbs ApS','new','A','Дания','Nykøbing Falster','info@windturbs.com','http://www.windturbs.com','','Сервис, ремонт и модернизация ветряков, работают и на море.','{"rank": 5, "fit_score": 9, "why": "Небольшая гибкая фирма. Во время модернизации и ремонта постоянно нужны мелкие детали и крепления.", "give": "Кронштейны, втулки, крышки и другие мелкие детали на сервис и модернизацию.", "lang": "da", "subject_da": "Beslag og bøsninger til service", "body_da": "Hej,\nJeg skriver, fordi I laver service, reparation og modernisering af vindmøller, også offshore. Ved den slags opgaver mangler man tit en lille del, f.eks. et beslag, en bøsning eller et dæksel. Det hjælper vi med at skaffe eller få fremstillet, også hvis det kun er få stykker. Kunne det være noget for jer, så send et billede eller en kort beskrivelse, så ser vi på det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Кронштейны и втулки для сервиса", "body_ru": "Здравствуйте,\nПишу вам, потому что вы занимаетесь сервисом, ремонтом и модернизацией ветряков, в том числе на море. При таких работах часто не хватает какой-нибудь небольшой детали, например кронштейна, втулки или крышки. С этим мы помогаем: подбираем или заказываем изготовление, даже если нужно всего несколько штук. Если это может быть вам интересно, пришлите фото или короткое описание, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','EB Teknik Borup A/S','new','A','Дания','Borup','info@ebteknik.dk','https://www.ebteknik.dk','','Машиностроительный завод: линии розлива и упаковки для пивоварен, напитков и фармацевтики, сервис и запчасти.','{"rank": 6, "fit_score": 9, "why": "Свой склад запчастей и сервис линий розлива: на таких линиях много пластиковых направляющих, звездочек, ограничителей и колпачков.", "give": "Поставим пластиковые направляющие, ограничители, проставки и крышки для розливных линий по образцу малыми партиями.", "lang": "da", "subject_da": "Plastdele til tappelinjer", "body_da": "Hej,\nI bygger tappe- og pakkelinjer og servicerer dem bagefter, kan jeg se. På den slags linjer sidder der ofte plastdele som føringer, afstandsstykker og dæksler, der slides eller kun skal bruges i få eksemplarer. Dem kan vi hjælpe med at skaffe eller få fremstillet i små mængder. Har I en del, I bruger for meget tid på at få hjem, må I gerne sende et billede eller en prøve.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для линий розлива", "body_ru": "Здравствуйте,\nЯ вижу, что вы строите линии розлива и упаковки и потом их обслуживаете. На таких линиях часто стоят пластиковые детали, например направляющие, проставки и крышки, которые изнашиваются или нужны всего в нескольких экземплярах. Мы можем помочь подобрать или изготовить их в небольших количествах. Если у вас есть деталь, на получение которой уходит слишком много времени, пришлите, пожалуйста, фото или образец.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','H-Elevator','new','A','Дания','Sabro (Aarhus)','info@h-elevator.dk','https://h-elevator.dk','','Независимая сервисная компания по лифтам, подъёмникам и эскалаторам в Центральной и Восточной Ютландии.','{"rank": 7, "fit_score": 9, "why": "Независимый небольшой сервис без привязки к производителю, у которого есть собственная мастерская, и они подчёркивают, что не хотят месяцами ждать запчасти из-за рубежа. Пластиковые направляющие, крышки и кнопочные накладки для старых лифтов — типичная потребность.", "give": "Изготовим по образцу пластиковые направляющие, накладки, крышки и втулки для лифтов малыми партиями с коротким сроком.", "lang": "da", "subject_da": "Dele til ældre elevatorer", "body_da": "Hej,\nDet ser ud til, at I servicerer elevatorer, lifte og rulletrapper uafhængigt og har eget værksted. Ældre anlæg har ofte små plastdele, der er slidte eller ikke længere fås, f.eks. føringer, dæksler og bøsninger. Den slags kan vi hjælpe med at skaffe eller få fremstillet i små mængder. Tag et billede af en del, I mangler, og send det til os. Det tager kun et øjeblik, og så ser vi på sagen.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Детали для старых лифтов", "body_ru": "Здравствуйте,\nПохоже, что вы независимо обслуживаете лифты, подъёмники и эскалаторы и у вас есть своя мастерская. На старых установках часто бывают небольшие пластиковые детали, которые изношены или больше не продаются, например направляющие, крышки и втулки. Мы можем помочь подобрать или изготовить такое в небольших количествах. Сфотографируйте деталь, которой вам не хватает, и пришлите нам. Это займёт минуту, а дальше мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Kroma A/S','new','A','Дания','Skive','sparepart@kroma.dk','https://kroma.dk','','Производит машины для обработки рыбы (потрошение, филетирование) и оказывает сервис по всему миру.','{"rank": 8, "fit_score": 9, "why": "Малый производитель с собственным отделом запчастей: у станков для рыбы много небольших пластиковых направляющих, крышек и втулок. Мелкие партии запчастей для старых моделей — типичная боль.", "give": "Изготовим небольшие партии пластиковых втулок, направляющих, крышек и кронштейнов по образцу или чертежу для их запчастей.", "lang": "da", "subject_da": "Små plastdele til fiskemaskiner", "body_da": "Hej,\nJeg ser, at I bygger maskiner til fiskebearbejdning og har en reservedelsafdeling. Vi skaffer og får fremstillet små plastdele i få styk, f.eks. føringer, bøsninger og dæksler. Det kan måske være en hjælp, når en ældre model skal have en ny del, og mængden er for lille til en stor ordre. Send os gerne et billede, en tegning eller selve delen, så ser vi på den.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие пластиковые детали для рыбных машин", "body_ru": "Здравствуйте,\nЯ вижу, что вы строите машины для обработки рыбы и у вас есть отдел запчастей. Мы подбираем и заказываем изготовление небольших пластиковых деталей в единичных экземплярах, например направляющих, втулок и крышек. Возможно, это поможет, когда для старой модели нужна новая деталь, а количество слишком мало для крупного заказа. Пришлите нам фото, чертёж или саму деталь, и мы её посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Maskinplus.dk ApS','new','A','Дания','Karlslunde','info@maskinplus.dk','https://maskinplus.dk/','','Ремонт и сервис станков и промышленных машин, поиск запчастей для старого и уникального оборудования с 1982 года.','{"rank": 9, "fit_score": 9, "why": "Ищут трудно доставаемые запчасти для старых станков, где сроки долгие, а детали сняты с производства, это ровно наша ниша.", "give": "Изготовление копий и аналогов мелких пластиковых запчастей по образцу для старых и снятых с производства станков.", "lang": "da", "subject_da": "Udgåede plastdele til maskiner", "body_da": "Hej,\nI leder efter svært tilgængelige reservedele til ældre maskiner, har jeg forstået. Det er faktisk også det, vi arbejder med, når det gælder plastdele: bøsninger, dæksler, afstandsstykker og lignende i små mængder. Hvis I har en kunde med en udgået plastdel, kan I sende et billede eller selve delen. Så ser vi på, om vi kan lave en kopi eller finde noget tilsvarende.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Снятые с производства пластиковые детали для станков", "body_ru": "Здравствуйте,\nКак я понял, вы ищете труднодоступные запчасти для старых станков. Именно этим мы и занимаемся, когда речь идёт о пластиковых деталях: втулки, крышки, проставки и подобное в небольших количествах. Если у вас есть клиент со снятой с производства пластиковой деталью, пришлите фото или саму деталь. Мы посмотрим, сможем ли сделать копию или найти что-то подходящее.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','TMS Partner','new','A','Дания','Herning (Gjellerup)','tms@tmspartner.dk','https://tmspartner.dk/','','Промышленный сервис, ремонт и обслуживание оборудования, монтаж и слесарная мастерская в Центральной и Западной Ютландии.','{"rank": 10, "fit_score": 9, "why": "Сами делают запчасти для заказчиков и уже предлагают 3D-печатные пластиковые элементы, поэтому регулярно сталкиваются с потребностью в мелких пластиковых деталях.", "give": "Изготовление мелких пластиковых запчастей (втулки, кронштейны, крышки, направляющие) малыми партиями по образцу или чертежу для их клиентов.", "lang": "da", "subject_da": "Plastdele til jeres kunders udstyr", "body_da": "Hej,\nJeg bemærkede, at I har både værksted og service i Midt- og Vestjylland og tager jer af vedligehold af udstyr. Så oplever I sikkert også, at en lille plastdel mangler, mens resten af maskinen fint kan køre videre. Vi kan hjælpe med bøsninger, beslag, dæksler og føringer i små mængder. Send gerne en prøve eller et billede, så svarer vi ærligt, om det er noget for os.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для оборудования ваших клиентов", "body_ru": "Здравствуйте,\nЯ заметил, что у вас есть и мастерская, и сервис в Центральной и Западной Ютландии, и вы занимаетесь обслуживанием оборудования. Значит, вы, наверное, тоже сталкиваетесь с тем, что не хватает маленькой пластиковой детали, хотя остальная машина вполне может работать. Мы можем помочь со втулками, кронштейнами, крышками и направляющими в небольших количествах. Пришлите образец или фото, и мы честно ответим, подходит ли это нам.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Toft Automation A/S','new','A','Дания','Spentrup','kontakt@toft-automation.dk','https://www.toft-automation.dk','','Производитель щитов управления и шкафов, монтаж машинных линий и ПЛК-программирование.','{"rank": 11, "fit_score": 9, "why": "Сборщик щитов, которому постоянно нужны небольшие пластиковые элементы: кабельные вводы, держатели, крышки и направляющие для DIN-реек. Нужны небольшие партии под конкретные проекты.", "give": "Изготовим кастомные пластиковые держатели, крышки, кабельные вводы и распорки для электрощитов малыми партиями.", "lang": "da", "subject_da": "Gennemføringer og holdere til tavler", "body_da": "Hej,\nVi hjælper med små plastdele i få styk, bl.a. til maskiner og udstyr. Da I bygger styretavler og monterer maskinlinjer, tænker jeg på ting som kabelgennemføringer, holdere, dæksler og afstandsstykker, når standarddelene ikke passer til et bestemt projekt. Dem kan vi skaffe eller få lavet. Har I et konkret behov, så send et billede eller en kort beskrivelse, så ser vi på det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Кабельные вводы и держатели для щитов", "body_ru": "Здравствуйте,\nМы помогаем с мелкими пластиковыми деталями в небольшом количестве, в частности для машин и оборудования. Раз вы собираете щиты управления и монтируете машинные линии, я думаю о таких вещах, как кабельные вводы, держатели, крышки и проставки, когда стандартные детали не подходят под конкретный проект. Их мы можем подобрать или изготовить. Если у вас есть конкретная потребность, пришлите фото или короткое описание, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Connected Wind Services Danmark A/S','new','A','Дания','Skødstrup','Bo.Damsgaard@connectedwind.com','https://www.connectedwind.com','Bo Kirk Damsgaard (руководитель продаж)','Крупный независимый сервис ветряков, 1700+ турбин разных брендов.','{"rank": 12, "fit_score": 8, "why": "Много старых платформ и брендов, где поставки от производителя нестабильны. Большая компания, но контакт по продажам в Дании публичный.", "give": "Мелкие пластиковые детали для старых турбин, которые долго ждать или дорого покупать.", "lang": "da", "subject_da": "Små plastdele til ældre møller", "body_da": "Hej Bo,\nJeg skriver til dig, fordi I servicerer vindmøller af mange forskellige mærker. Vi er et lille firma, som skaffer og får fremstillet mindre plastdele til udstyr, f.eks. dæksler, bøsninger og beslag. Det kan være relevant, når en del er dyr eller tager lang tid at få fra producenten. Hvis du har et eksempel, så send et foto eller en kort beskrivelse, så kigger vi på den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие пластиковые детали для старых турбин", "body_ru": "Здравствуйте, Бо,\nПишу вам, потому что вы обслуживаете ветряки самых разных марок. Мы небольшая фирма, которая подбирает и заказывает изготовление небольших пластиковых деталей для оборудования, например крышек, втулок и кронштейнов. Это может быть актуально, когда деталь дорогая или её долго ждать от производителя. Если у вас есть пример, пришлите фото или короткое описание. Мы с радостью посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','enervisual','new','A','Дания','Дания','info@enervisual.com','https://enervisual.com','','Датский стартап: беспроводные датчики вибрации и мониторинга для ветряков.','{"rank": 13, "fit_score": 8, "why": "Каждой установке нужны крепления под разные типы турбин, а стартапу выгодно не держать свою мастерскую.", "give": "Кронштейны и монтажные детали для датчиков под разные типы турбин.", "lang": "da", "subject_da": "Beslag til sensorer", "body_da": "Hej,\nJeg så, at I laver trådløse vibrationssensorer til vindmøller. Når de skal monteres på forskellige mølletyper, skal der vel tit bruges små beslag eller holdere, som passer til den enkelte opgave. Det kan vi hjælpe med at skaffe eller få fremstillet i plast, også i små serier. Hvis I har en skitse eller et billede af, hvad I skal bruge, så send det gerne. Det kigger vi gerne nærmere på.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Кронштейны для датчиков", "body_ru": "Здравствуйте,\nЯ увидел, что вы делаете беспроводные датчики вибрации для ветряков. Когда их монтируют на разные типы турбин, наверное, часто нужны небольшие кронштейны или держатели под конкретную задачу. С этим мы можем помочь: подобрать или изготовить их из пластика, в том числе малыми сериями. Если у вас есть эскиз или фото того, что нужно, пришлите, пожалуйста. Посмотрим с интересом.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Nordic Wind Technology ApS','new','A','Дания','Silkeborg','info@nordicwindtechnology.com','https://nordicwindtechnology.com','','Модернизация контроллеров ветряков, 550+ установок.','{"rank": 14, "fit_score": 8, "why": "На каждый retrofit нужны мелкие монтажные детали: клипсы, крышки, пластины, кронштейны.", "give": "Мелкие монтажные детали под их установки малыми партиями.", "lang": "da", "subject_da": "Monteringsdele i plast", "body_da": "Hej,\nI opgraderer styringer på vindmøller, og jeg kan se, at I har gjort det på mange anlæg. Ved den slags opgaver er der ofte brug for små ting som clips, dæksler, plader og beslag, der ikke lige findes hos en standardleverandør. Dem kan vi skaffe eller få fremstillet i små mængder. Skriv endelig tilbage med et billede eller et par linjer om, hvad I mangler.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Монтажные детали из пластика", "body_ru": "Здравствуйте,\nВы модернизируете системы управления ветряков, и я вижу, что делали это на многих установках. При таких работах часто нужны мелочи вроде клипс, крышек, пластин и кронштейнов, которых нет у стандартного поставщика. Мы можем подобрать или изготовить их в небольших количествах. Напишите в ответ и приложите фото или пару строк о том, чего вам не хватает.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','WindX UCP ApS','new','A','Дания','Rønde','ag@windxucp.com','https://www.windxucp.com','','Новое датско-китайское СП по сервису ветряков (основано в 2025), есть склад и запчасти.','{"rank": 15, "fit_score": 8, "why": "Новая компания, которая как раз сейчас собирает поставщиков для работы в Дании. Почта склада и запчастей публичная.", "give": "Стать локальным источником мелких пластиковых деталей и креплений для их склада и сервиса.", "lang": "da", "subject_da": "Lokal kilde til små plastdele", "body_da": "Hej,\nJeg læste, at I er et nyt selskab inden for vindmølleservice med reservedele i Danmark. Hvis I mangler en lokal kilde til små plastdele og fastgørelsesdele, kan vi måske være det. Vi tager os af bl.a. bøsninger, dæksler og beslag i mindre mængder. Send os et billede af en del eller en kort beskrivelse, så ser vi på det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Местный источник мелких пластиковых деталей", "body_ru": "Здравствуйте,\nЯ прочитал, что вы новая компания в сфере сервиса ветряков, и у вас есть запчасти в Дании. Если вам нужен местный источник небольших пластиковых и крепёжных деталей, возможно, им можем стать мы. Мы занимаемся, в частности, втулками, крышками и кронштейнами в небольших количествах. Пришлите нам фото детали или короткое описание, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','2Refurb A/S','new','A','Дания','Silkeborg','info@2refurb.com','https://2refurb.com/','','Датская компания: восстановление компонентов ветротурбин, инжиниринг и реверс-инжиниринг, поставка запчастей и сервисных деталей.','{"rank": 16, "fit_score": 8, "why": "Прямо заявляет об инжиниринге аналогов недоступных деталей и о собственной линейке альтернативных запчастей. Хороший партнёр для пластиковых запчастей по образцу.", "give": "Изготовление пластиковых аналогов мелких запчастей по образцу или чертежу (крышки, кронштейны, втулки, клипсы) малыми партиями для их собственной линейки.", "lang": "da", "subject_da": "Alternativer til udgåede plastdele", "body_da": "Hej,\nJeg så, at I både istandsætter komponenter til vindmøller og udvikler alternativer til dele, som ikke er til at få. Hvis en af dem er en lille plastdel, f.eks. et dæksel, en bøsning eller et beslag, kan vi måske hjælpe med at skaffe eller få den fremstillet. Det kan være i få styk. Send gerne en prøve eller et billede, så vender vi tilbage med et forslag.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Аналоги снятых с производства пластиковых деталей", "body_ru": "Здравствуйте,\nЯ увидел, что вы и восстанавливаете компоненты ветряков, и разрабатываете аналоги деталей, которые невозможно достать. Если среди них есть небольшая пластиковая деталь, например крышка, втулка или кронштейн, возможно, мы сможем помочь подобрать или изготовить её. Это может быть несколько штук. Пришлите образец или фото, и мы вернёмся с предложением.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Agri Teknik ApS','new','A','Дания','Brørup','post@agriteknik.dk','https://agriteknik.dk','','Монтаж и сервис доильных залов и охлаждения молока (BouMatic, Strangko, SAC) по всей Дании.','{"rank": 17, "fit_score": 8, "why": "Обслуживают доильные установки разного возраста, где доступ к запчастям определяет срок службы; мелкие пластиковые детали (крышки, держатели, втулки) нужны быстро и в малом количестве.", "give": "Пластиковые держатели, крышки, втулки и зажимы для доильного оборудования по образцу, малыми сериями.", "lang": "da", "subject_da": "Plastdele til malkeanlæg", "body_da": "Hej,\nVi hjælper med at skaffe små plastdele, og jeg tænkte på jer, fordi I servicerer malkeanlæg og mælkekøling. På ældre anlæg er det ofte de små ting, som holdere, dæksler og bøsninger, der driller. Dem kan vi skaffe eller få lavet i små mængder. Har I en, der driller lige nu, så tag et billede og send det, eller læg en prøve i en kuvert.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для доильных установок", "body_ru": "Здравствуйте,\nМы помогаем подбирать небольшие пластиковые детали, и я подумал о вас, потому что вы обслуживаете доильные установки и охлаждение молока. На старых установках часто именно мелочи, такие как держатели, крышки и втулки, создают проблемы. Их мы можем подобрать или изготовить в небольших количествах. Если сейчас есть такая деталь, сфотографируйте и пришлите, или положите образец в конверт.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Boleto ApS','new','A','Дания','Vamdrup','boleto@boleto.dk','https://www.boleto.dk','','Небольшой производитель машин для забоя и обработки рыбы, с 1972 года, обслуживает уже проданные машины.','{"rank": 18, "fit_score": 8, "why": "Выпускает машины малыми сериями и обслуживает парк старых машин (более 400 штук): нужны мелкие запчасти, которые трудно купить у стороннего поставщика.", "give": "Предложим пластиковые запчасти и простые детали для обслуживания их машин в малом количестве по образцу.", "lang": "da", "subject_da": "Reservedele til gamle fiskemaskiner", "body_da": "Hej,\nJeg forstår, at I har lavet maskiner til slagtning og bearbejdning af fisk siden 1972 og stadig servicerer mange af de gamle. Det kan være, at nogle små plastdele er besværlige at få fra en ekstern leverandør i få styk. Det er den slags, vi gerne vil hjælpe med: bøsninger, dæksler, føringer og lignende. Send et billede eller selve delen, så giver vi et ærligt svar.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для старых рыбных машин", "body_ru": "Здравствуйте,\nКак я понимаю, с 1972 года вы делаете машины для забоя и обработки рыбы и до сих пор обслуживаете многие старые. Возможно, некоторые небольшие пластиковые детали трудно получить у внешнего поставщика в единичных экземплярах. Именно с этим мы и хотим помогать: втулки, крышки, направляющие и подобное. Пришлите фото или саму деталь, и мы дадим честный ответ.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Brdr. Petersen Gilleleje A/S','new','A','Дания','Gilleleje','info@brdrpetersen.dk','https://www.brdrpetersen.dk','','Машиностроительная мастерская и судовой сервис: двигатели, судовая электроника, проверка оборудования, магазин для лодок.','{"rank": 19, "fit_score": 8, "why": "Универсальная мастерская для рыболовных и прогулочных судов с магазином запчастей; часто сталкиваются с мелкими деталями, которых нет в наличии.", "give": "Мелкосерийное изготовление пластиковых втулок, заглушек, кронштейнов и крышек для их сервиса и магазина.", "lang": "da", "subject_da": "Små dele til både og motorer", "body_da": "Hej,\nJeg kan se, at I har værksted og butik til både, med motorer og skibselektronik. Små plastdele som hætter, bøsninger, dæksler og beslag er tit dem, der mangler, og de kan ikke altid købes enkeltvis. Dem skaffer vi eller får fremstillet i små mængder. Har I en del, I har svært ved at finde, så send et billede eller en kort beskrivelse.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие детали для лодок и моторов", "body_ru": "Здравствуйте,\nЯ вижу, что у вас есть мастерская и магазин для лодок, с моторами и судовой электроникой. Маленькие пластиковые детали, такие как колпачки, втулки, крышки и кронштейны, часто как раз и не хватает, а по одной их не всегда можно купить. Мы подбираем или заказываем их изготовление в небольших количествах. Если есть деталь, которую трудно найти, пришлите фото или короткое описание.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Daltec A/S','new','A','Дания','Egtved','daltec@daltec.com','https://daltec.dk','','Датский производитель кормовых систем для свиноводства, КРС, птицы и аквакультуры.','{"rank": 20, "fit_score": 8, "why": "Системы кормления содержат много мелких пластиковых компонентов (кормовые ящики, направляющие, втулки, крышки, зажимы), а производство компонентов осталось в Дании.", "give": "Небольшие серии пластиковых направляющих, втулок, зажимов и крышек для компонентов кормовых линий и запасных частей.", "lang": "da", "subject_da": "Reservedele til foderanlæg", "body_da": "Hej,\nVi hjælper med små plastdele og reservedele. Jeg har set, at I laver foderanlæg til svin, kvæg, fjerkræ og akvakultur. I sådanne anlæg sidder der mange små komponenter som føringer, bøsninger, klemmer og dæksler, og nogle skal sikkert bruges i få styk som reservedele. Dem kan vi skaffe eller få fremstillet. Send gerne et billede eller en prøve, så ser vi på den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для кормовых систем", "body_ru": "Здравствуйте,\nМы помогаем с мелкими пластиковыми деталями и запчастями. Я посмотрел, что вы делаете кормовые системы для свиней, КРС, птицы и аквакультуры. В таких системах много мелких компонентов, например направляющих, втулок, зажимов и крышек, и некоторые, вероятно, нужны в нескольких экземплярах в качестве запчастей. Их мы можем подобрать или изготовить. Пришлите фото или образец, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Danwind ApS','new','A','Дания','Lemvig','sales@danwind.com','https://danwind.com/','','Датский поставщик критических и снятых с производства запчастей для ветротурбин разных брендов по всему миру.','{"rank": 21, "fit_score": 8, "why": "Специализируется на поиске устаревших запчастей, поэтому мелкие пластиковые детали, которые трудно найти, для них постоянная задача. Возможна работа как с альтернативным поставщиком.", "give": "Изготовление аналогов снятых с производства мелких пластиковых деталей (крышки, втулки, клипсы, кронштейны) малыми партиями для их каталога.", "lang": "da", "subject_da": "Udgåede plastdele til vindmøller", "body_da": "Hej,\n\nDet ser ud til, at I skaffer reservedele til vindmøller, også dele der ikke bliver produceret mere. Vi arbejder med små plastdele og reservedele i mindre mængder, fx dæksler, bøsninger, clips og beslag. Hvis der er en lille del, som er svær at finde eller kun kan fås i store partier, må I gerne sende et billede eller en kort beskrivelse. Så ser vi på den og skriver tilbage, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для ветротурбин", "body_ru": "Здравствуйте,\n\nПохоже, что вы поставляете запчасти для ветротурбин, в том числе детали, которые больше не выпускаются. Мы занимаемся небольшими пластиковыми деталями и запчастями в малых количествах, например крышками, втулками, клипсами и кронштейнами. Если есть мелкая деталь, которую трудно найти или которую продают только большими партиями, пришлите, пожалуйста, фото или короткое описание. Мы посмотрим и напишем вам, если сможем решить этот вопрос.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Decowicon','new','A','Дания','Brande','wind@decowicon.com','https://decowicon.com','','Небольшая компания по сервису и ремонту ветротурбин Nordex, поставка запчастей и консультации.','{"rank": 22, "fit_score": 8, "why": "Держит на складе «мелкие детали» и закупает запчасти для Nordex, поэтому регулярно сталкивается с поиском недорогих мелких деталей. Небольшая фирма — решения принимаются быстро.", "give": "Быстро изготовим по образцу мелкие пластиковые запчасти (крышки, втулки, клипсы, проходки) для Nordex и других турбин в малых количествах.", "lang": "da", "subject_da": "Små dele til Nordex-møller", "body_da": "Hej,\n\nDa I servicerer Nordex-møller, har I nok indimellem brug for en lille plastdel, som er dyr eller besværlig at få hjem enkeltvis. Det kunne være et dæksel, en bøsning eller en gennemføring. Vi skaffer og får fremstillet den slags i små mængder. Har I en sådan del, så send os et billede eller en prøve, så ser vi på den og giver et konkret svar.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие детали для Nordex", "body_ru": "Здравствуйте,\n\nПоскольку вы обслуживаете турбины Nordex, вам, наверное, время от времени нужна маленькая пластиковая деталь, которая стоит дорого или которую трудно заказать поштучно. Это может быть крышка, втулка или кабельный ввод. Мы подбираем и изготавливаем такие детали в малых количествах. Если у вас есть такая деталь, пришлите нам фото или образец, мы посмотрим и дадим конкретный ответ.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Ehcolo A/S','new','A','Дания','Føvling','spareparts@ehcolo.dk','https://ehcolo.com/da/','','Производитель паллетайзеров, машин для стрейч-худ плёнки и упаковочных линий.','{"rank": 23, "fit_score": 8, "why": "На сайте есть отдельный контакт для запчастей (spareparts@), то есть они продают запчасти клиентам по всему миру. Машины работают десятилетиями, и мелкие пластиковые детали нужны постоянно.", "give": "Предложим мелкие пластиковые детали для их запчастей: втулки, крышки, направляющие, кронштейны в малых сериях.", "lang": "da", "subject_da": "Reservedele til pakkemaskiner", "body_da": "Hej,\n\nJeg bemærkede, at I bygger palleteringsmaskiner og indpakningsanlæg og har en separat mailadresse til reservedele. Til ældre maskiner kan det være styreskinner, bøsninger eller små dæksler, der bliver dyre eller svære at få i få styk. Dem vil vi gerne se på, også selvom det kun drejer sig om en lille mængde. Send et billede af delen, så vender vi tilbage, hvis vi kan hjælpe.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для упаковочных машин", "body_ru": "Здравствуйте,\n\nЯ заметил, что вы производите паллетайзеры и упаковочные линии, и у вас есть отдельный адрес для запчастей. Для старых машин это могут быть направляющие, втулки или небольшие крышки, которые становятся дорогими или их трудно получить в малом количестве. Мы с удовольствием на них посмотрим, даже если речь идёт о небольшом количестве. Пришлите фото детали, и мы вернёмся к вам, если сможем помочь.\n\nС ув.\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','FH Trykluft ApS','new','A','Дания','Hornslet','mail@fh-trykluft.dk','https://fh-trykluft.dk','','Сервис, ремонт и продажа компрессоров, специализация Atlas Copco, держат восстановленные запчасти к машинам старше 40 лет.','{"rank": 24, "fit_score": 8, "why": "Работают с очень старыми компрессорами, для которых оригинальные пластиковые детали (крышки, ручки, кожухи, держатели) уже не продают. Небольшая фирма, которой подходят малые партии.", "give": "Изготовим по образцу пластиковые крышки, рукоятки, втулки и кабельные вводы для старых компрессоров малыми сериями.", "lang": "da", "subject_da": "Plastdele til ældre kompressorer", "body_da": "Hej,\n\nJeg læste, at I reparerer kompressorer og også har dele til meget gamle maskiner. Når originale dæksler, håndtag eller holdere ikke findes mere, kan vi måske hjælpe. Vi får lavet små plastdele i få eksemplarer ud fra en prøve. Send et billede eller selve delen, så kigger vi på den og kommer med et forslag, hvis det kan lade sig gøre.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых компрессоров", "body_ru": "Здравствуйте,\n\nЯ прочитал, что вы ремонтируете компрессоры и держите запчасти даже для очень старых машин. Когда оригинальные крышки, ручки или держатели больше не продаются, мы, возможно, сможем помочь. Мы заказываем небольшие пластиковые детали в единичных экземплярах по образцу. Пришлите фото или саму деталь, мы посмотрим и предложим вариант, если это возможно.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Form & Frys Maskinteknik','new','A','Дания','Hobro','formfrys@formfrys.dk','http://www.formfrys.dk','','Строит машины для складывания, формования и наполнения тестовых изделий для промышленных пекарен.','{"rank": 25, "fit_score": 8, "why": "Небольшой производитель машин по заказу: нужны нестандартные пластиковые детали в штучных количествах и запчасти для машин у клиентов.", "give": "Сделаем пластиковые формовочные и направляющие детали, втулки и крышки малыми партиями.", "lang": "da", "subject_da": "Plastdele til jeres maskiner", "body_da": "Hej,\n\nJeg ser, at I bygger maskiner til industribagerier, bl.a. til at folde og forme dej. Til den slags maskiner er der somme tider brug for en enkelt føring, en bøsning eller et dæksel i plast, som ikke findes som standard. Det er den slags, vi hjælper med i små mængder. Send gerne et billede af en del, I har brug for, så ser vi, om vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для ваших машин", "body_ru": "Здравствуйте,\n\nЯ вижу, что вы строите машины для промышленных пекарен, в том числе для складывания и формования теста. Для таких машин иногда нужна одна направляющая, втулка или крышка из пластика, которой нет в стандартном ассортименте. Именно с такими вещами мы помогаем в малых количествах. Пришлите, пожалуйста, фото нужной вам детали, и мы посмотрим, сможем ли решить задачу.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Grimstrup Maskiner ApS','new','A','Дания','Varde','info@grimstrup-maskiner.dk','https://grimstrup-maskiner.dk/','','Сервис, ремонт и переоборудование заводских линий и машин, изготовление и восстановление запчастей в юго-западной Ютландии.','{"rank": 26, "fit_score": 8, "why": "Занимаются ремонтом и ТО технологических линий и сами изготавливают запчасти, значит им часто нужны мелкие пластиковые компоненты быстро и в малых количествах.", "give": "Быстрое изготовление пластиковых втулок, заглушек, направляющих и кронштейнов штучно или малыми сериями для их сервисных работ.", "lang": "da", "subject_da": "Små plastdele til servicearbejde", "body_da": "Hej,\n\nVi hjælper med små plastdele og reservedele i få styk. Da I reparerer og ombygger produktionslinjer, støder I nok på dele, hvor det ikke giver mening at bestille en hel serie. Bøsninger, hætter og små beslag er typiske eksempler. Send os gerne et billede eller en kort beskrivelse af en konkret del, så vender vi tilbage med et forslag, hvis vi kan lave den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие пластиковые детали для сервиса", "body_ru": "Здравствуйте,\n\nМы помогаем с небольшими пластиковыми деталями и запчастями в малых количествах. Поскольку вы ремонтируете и переоборудуете производственные линии, вам, наверное, попадаются детали, для которых нет смысла заказывать целую серию. Типичные примеры: втулки, колпачки и небольшие кронштейны. Пришлите нам фото или короткое описание конкретной детали, и мы вернёмся с предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Hovedstadens Elevator Service A/S','new','A','Дания','København','info@heselevator.dk','https://hovedstadenselevatorservice.dk','','Сервис и ремонт лифтов и грузовых подъёмников в Копенгагене и на Зеландии, более 35 лет на рынке.','{"rank": 27, "fit_score": 8, "why": "Независимый сервис, ремонтирует разные типы лифтов, в том числе старые, где оригинальные мелкие детали часто сняты с производства. Нужны небольшие количества пластиковых деталей.", "give": "Дублируем сломанные пластиковые детали (рамки, колпачки, направляющие, кнопочные части) по образцу в малых тиражах.", "lang": "da", "subject_da": "Plastdele til ældre elevatorer", "body_da": "Hej,\n\nJeg forstår, at I servicerer elevatorer i København og på Sjælland, også ældre typer. Når en lille plastdel går i stykker, og den ikke kan skaffes mere, kan vi måske få lavet en ud fra den gamle. Det kan være en afdækning, en hætte eller en føring. Har I sådan en del, må I gerne sende et billede og et par ord om den, så svarer vi.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых лифтов", "body_ru": "Здравствуйте,\n\nКак я понимаю, вы обслуживаете лифты в Копенгагене и на Зеландии, в том числе старые модели. Когда ломается маленькая пластиковая деталь и её больше нельзя достать, мы, возможно, сможем изготовить такую же по старой. Это может быть накладка, колпачок или направляющая. Если у вас есть такая деталь, пришлите фото и пару слов о ней, и мы ответим.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Ingvald Christensen A/S Maskinfabrik','new','A','Дания','Odense','info@ingvald.dk','https://ingvald.dk','','Поставляет, обслуживает и ремонтирует мясоперерабатывающие машины (волчки, вакуумные шприцы, клипсаторы) с 1938 года.','{"rank": 28, "fit_score": 8, "why": "Большой сервисный склад запчастей для разных марок мясных машин; многие пластиковые детали старых моделей трудно найти.", "give": "Сделаем пластиковые аналоги запчастей (втулки, направляющие, крышки) для старых машин малыми партиями.", "lang": "da", "subject_da": "Plastdele til kødmaskiner", "body_da": "Hej,\n\nJeg kan se, at I har leveret og serviceret kødmaskiner siden 1938. Til ældre modeller kan små plastdele som bøsninger, føringer og dæksler være svære at skaffe. Det prøver vi at hjælpe med, også når det kun er et par stykker. Send et billede af delen eller en kort beskrivelse, så ser vi på den og giver besked, om vi kan klare den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для мясных машин", "body_ru": "Здравствуйте,\n\nЯ вижу, что вы с 1938 года поставляете и обслуживаете машины для мясной промышленности. Для старых моделей маленькие пластиковые детали, такие как втулки, направляющие и крышки, бывает трудно найти. Мы стараемся помочь и с этим, даже если нужно всего несколько штук. Пришлите фото детали или короткое описание, мы посмотрим и сообщим, справимся ли.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','JG Teknik ApS','new','A','Дания','Rønde','kontakt@jg-teknik.dk','https://jg-teknik.dk','','Небольшая компания, строящая специальные машины, программирующая ПЛК и обслуживающая автоматику.','{"rank": 29, "fit_score": 8, "why": "Маленький производитель спецмашин постоянно нуждается в нестандартных пластиковых деталях в единичных количествах (направляющие, крышки, кронштейны). Малые партии для них дороги и долго ждать у крупных поставщиков.", "give": "Изготовим небольшие партии пластиковых кронштейнов, направляющих, втулок и крышек по образцу или чертежу.", "lang": "da", "subject_da": "Enkeltdele til specialmaskiner", "body_da": "Hej,\n\nDa I bygger specialmaskiner, er der vel også tit brug for én lille plastdel, som ingen har på hylden. Vi skaffer og får fremstillet beslag, føringer og dæksler i helt små mængder, også når det kun er en enkelt. Hvis I har en tegning, en prøve eller bare et billede, så send det endelig. Så ser vi, om det er noget, vi kan hjælpe med.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Единичные детали для спецмашин", "body_ru": "Здравствуйте,\n\nПоскольку вы строите специальные машины, вам, наверное, часто нужна одна маленькая пластиковая деталь, которой ни у кого нет в наличии. Мы подбираем и изготавливаем кронштейны, направляющие и крышки в совсем малых количествах, даже если нужна всего одна. Если у вас есть чертёж, образец или просто фото, присылайте. Мы посмотрим, сможем ли мы с этим помочь.\n\nС ув.\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','JOM A/S (JOM Rustfri)','new','A','Дания','Thisted','info@jomrustfri.dk','https://jomrustfri.dk','','Мастерская в Thisted, строит специальные машины из нержавейки для бойни, молочных и хлебопекарных предприятий.','{"rank": 30, "fit_score": 8, "why": "Небольшой производитель, который сам указывает на потребность в запчастях и быстром сервисе; для их линий нужны индивидуальные пластиковые детали в штучных количествах.", "give": "Поставим небольшие партии пластиковых деталей и запчастей для их машин и сервисных заказов по чертежу или образцу.", "lang": "da", "subject_da": "Plastdele til rustfri maskiner", "body_da": "Hej,\n\nJeg har set, at I bygger specialmaskiner i rustfrit stål til slagterier, mejerier og bagerier. Vi tager os af de små plastdele, fx bøsninger, føringer eller dæksler, også når det kun er få stykker. Hvis der er en del, I mangler til en maskine eller et servicearbejde, så send et billede eller en tegning. Vi kigger på den og svarer, om vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для машин из нержавейки", "body_ru": "Здравствуйте,\n\nЯ видел, что вы строите специальные машины из нержавеющей стали для скотобоен, молочных предприятий и пекарен. Мы занимаемся мелкими пластиковыми деталями, например втулками, направляющими или крышками, в том числе когда нужно всего несколько штук. Если вам не хватает детали для машины или для сервисной работы, пришлите фото или чертёж. Мы посмотрим и ответим, сможем ли мы это сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Jørns Malkemaskine Service ApS','new','B','Дания','Ølgod','info@staldteknik.dk','https://staldteknik.dk','','Небольшая семейная сервисная фирма по доильным установкам, роботам Gemini и системам навозоудаления.','{"rank": 31, "fit_score": 8, "why": "Обслуживают установки BouMatic, SAC и Gemini, в том числе снятые с производства (SAC), и сами заказывают много мелких запчастей; небольшой сервис выигрывает от местного поставщика.", "give": "Оперативное изготовление пластиковых запчастей для снятых с производства доильных и навозоуборочных систем.", "lang": "da", "subject_da": "Reservedele til malkeanlæg", "body_da": "Hej,\n\nJeg har set, at I servicerer malkeanlæg og udmugningsanlæg, også ældre anlæg. Der kan det være svært at få små plastdele hjem, fx hætter, bøsninger eller clips. Vi kan se på det, også hvis det kun er få stykker, og I behøver ikke at kende det rigtige navn på delen. Send et billede af en del, der driller, så vender vi tilbage, hvis vi kan lave en.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для доильных установок", "body_ru": "Здравствуйте,\n\nЯ посмотрел, что вы обслуживаете доильные установки и системы навозоудаления, в том числе старые. Там бывает трудно достать маленькие пластиковые детали, например колпачки, втулки или клипсы. Мы можем посмотреть, даже если нужно всего несколько штук, и вам не обязательно знать точное название детали. Пришлите фото детали, с которой возникла проблема, и мы вернёмся к вам, если сможем сделать такую.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Kaj Olesen A/S','new','B','Дания','Nr. Nebel','info@kajolesen.dk','https://www.kajolesen.com','','Выпускает оборудование для рыбопереработки (удаление костей, разделочные линии), около 20 сотрудников.','{"rank": 32, "fit_score": 8, "why": "Много индивидуального оборудования и собственная сервисная служба, которой нужны мелкие пластиковые детали и запчасти в малых количествах для машин, работающих по всему миру.", "give": "Быстро сделаем пластиковые кронштейны, прокладки, направляющие и колпачки малыми сериями для сервиса и новых машин.", "lang": "da", "subject_da": "Plastdele til fiskemaskiner", "body_da": "Hej,\n\nVi hjælper med at skaffe små plastdele og reservedele i mindre mængder. Jeg ser, at I bygger udstyr til fiskeindustrien, bl.a. til at skære og fjerne ben, og at maskinerne kører mange steder i verden. Til service og nye maskiner kan det være føringer, hætter eller beslag. Send et billede eller en kort beskrivelse af en del, så ser vi på den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для рыбных машин", "body_ru": "Здравствуйте,\n\nМы помогаем подбирать небольшие пластиковые детали и запчасти в малых количествах. Я вижу, что вы делаете оборудование для рыбной промышленности, в том числе для разделки и удаления костей, и что ваши машины работают во многих странах. Для сервиса и новых машин это могут быть направляющие, колпачки или кронштейны. Пришлите фото или короткое описание детали, и мы на неё посмотрим.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Københavns Yacht og Motorbåds Værft (KYMV)','new','B','Дания','Copenhagen','info@cph-yacht.dk','https://www.cph-yacht.dk','','Лодочная верфь с 1917 года: постройка, ремонт и реставрация парусных и моторных лодок в Копенгагене.','{"rank": 33, "fit_score": 8, "why": "Небольшая верфь, строящая и реставрирующая лодки и детали для них; нужны мелкие нестандартные пластиковые компоненты в малых объёмах.", "give": "Единичные и малые серии пластиковых деталей и комплектующих для реставрации и постройки лодок.", "lang": "da", "subject_da": "Små plastdele til bådrestaurering", "body_da": "Hej,\n\nJeg kan se, at værftet har bygget og restaureret både siden 1917. Ved ældre både er der ofte små ting, man ikke kan købe længere, fx afdækninger, bøsninger eller beslag i plast. Vi kan måske lave dem i ét eksemplar eller et par stykker. Har I en prøve eller et billede, så send det gerne, så kigger vi på den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие пластиковые детали для реставрации лодок", "body_ru": "Здравствуйте,\n\nЯ вижу, что верфь строит и реставрирует лодки с 1917 года. У старых лодок часто бывают мелочи, которые больше нельзя купить, например пластиковые накладки, втулки или кронштейны. Возможно, мы сможем сделать их в одном экземпляре или в нескольких штуках. Если у вас есть образец или фото, пришлите, и мы посмотрим.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','LBA – Specialmaskiner & Automation','new','B','Дания','København','info@lb-automation.dk','https://lb-automation.dk','','Копенгагенская фирма по автоматизации, спецмашинам и роботизированным решениям.','{"rank": 34, "fit_score": 8, "why": "Малый интегратор, который делает уникальные машины и ремонтирует старые установки, часто ищет запчасти, снятые с производства. Малые тиражи им нужны чаще всего.", "give": "Сделаем копии снятых с производства пластиковых деталей и мелкие крепёжные элементы в количестве от 1–10 штук.", "lang": "da", "subject_da": "Plastdele til ældre anlæg", "body_da": "Hej,\n\nEr der en plastdel i et ældre anlæg, som ikke kan skaffes mere? Det støder I vel på, når I bygger specialmaskiner og automation. Vi får lavet små plastdele som beslag, dæksler og bøsninger i meget små mængder, ofte ud fra en gammel del som model. Send et billede eller selve delen, så ser vi på den og vender tilbage, hvis vi kan lave en kopi.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых установок", "body_ru": "Здравствуйте,\n\nЕсть ли в старой установке пластиковая деталь, которую больше нельзя достать? С этим вы, наверное, сталкиваетесь, когда строите специальные машины и автоматику. Мы заказываем небольшие пластиковые детали, такие как кронштейны, крышки и втулки, в очень малых количествах, часто по старой детали как образцу. Пришлите фото или саму деталь, мы посмотрим и вернёмся к вам, если сможем сделать копию.\n\nС ув.\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Moderne Kornbehandling ApS','new','B','Дания','Tørring','info@mkorn.dk','https://mkorn.dk','','Монтаж и сервис кормовых, зерновых и транспортных систем, склад запчастей независимо от марки.','{"rank": 35, "fit_score": 8, "why": "Обслуживают разные марки (Skiold, Kongskilde, ACO Funki, Jema) и сами подчёркивают, что быстро находят нужную запчасть; для старых машин нужны нестандартные мелкие детали.", "give": "Поставка нестандартных пластиковых втулок, крышек, заглушек и направляющих по образцу в малых количествах.", "lang": "da", "subject_da": "Små dele til foderanlæg", "body_da": "Hej,\n\nJeg ser, at I servicerer foder- og kornanlæg uanset mærke, bl.a. Skiold og Kongskilde. Til ældre anlæg er det tit de små ting, der mangler, fx bøsninger, dæksler eller hætter i plast. Dem kan vi skaffe eller få lavet i små mængder. Sidder I med en del, der er svær at få fat i, så send os et billede, så ser vi på det.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие детали для кормовых систем", "body_ru": "Здравствуйте,\n\nЯ вижу, что вы обслуживаете кормовые и зерновые системы независимо от марки, в том числе Skiold и Kongskilde. Для старых систем часто не хватает именно мелочей, например пластиковых втулок, крышек или колпачков. Мы можем подобрать или изготовить их в малых количествах. Если у вас есть деталь, которую трудно достать, пришлите нам фото, и мы посмотрим.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Nordbjaergs ApS','new','B','Дания','Charlottenlund','info@nordbjaergs.dk','https://nordbjaergs.dk','','Верфь и магазин для парусных и моторных лодок: ремонт, обслуживание и продажа оборудования (Скавсховед-Хавн).','{"rank": 36, "fit_score": 8, "why": "Ремонтируют классические и современные лодки и имеют магазин; старые лодки часто требуют нестандартных мелких деталей, которых больше нет в продаже.", "give": "Изготовление копий мелких пластиковых деталей для старых лодок (заглушки, втулки, накладки, направляющие) малыми партиями.", "lang": "da", "subject_da": "Plastdele til gamle både", "body_da": "Hej,\n\nDa I reparerer og servicerer både, nyere som klassiske, kommer I sikkert ud for dele, der ikke findes mere. Vi skaffer og får lavet små plastdele i få styk, fx hætter, bøsninger, afdækninger eller føringer efter en prøve. Tag et billede af den, der mangler eller er gået i stykker, og send det til os. Så skriver vi tilbage, hvis vi kan hjælpe.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых лодок", "body_ru": "Здравствуйте,\n\nПоскольку вы ремонтируете и обслуживаете лодки, как новые, так и классические, вы наверняка сталкиваетесь с деталями, которых больше нет в продаже. Мы подбираем и заказываем небольшие пластиковые детали в малом количестве по образцу, например колпачки, втулки, накладки или направляющие. Сфотографируйте недостающую или сломанную деталь и пришлите нам. Мы напишем в ответ, если сможем помочь.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Nordland Automatic A/S','new','B','Дания','Nørresundby','nordland@nordland.dk','https://nordland.dk','','Интегратор промышленных роботов и специальных машин в Северной Ютландии.','{"rank": 37, "fit_score": 8, "why": "Интегратор роботизированных ячеек использует много нестандартных захватов, держателей и защитных деталей. Мелкие пластиковые детали быстрее и дешевле сделать на месте, чем заказывать у крупных поставщиков.", "give": "Изготовим пластиковые губки захватов, держатели, прокладки и защитные крышки для роботизированных ячеек.", "lang": "da", "subject_da": "Plastdele til robotceller", "body_da": "Hej,\n\nVi hjælper med små plastdele og reservedele i mindre antal. Det ser ud til, at I integrerer industrirobotter og bygger specialmaskiner, og der er det ofte de små tilpassede dele, der skal til, fx holdere, afstandsstykker og dæksler. Bestiller I noget i dag, der er dyrt eller tager lang tid, så send et billede eller en kort beskrivelse. Vi ser på det og svarer konkret.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для роботизированных ячеек", "body_ru": "Здравствуйте,\n\nМы помогаем с небольшими пластиковыми деталями и запчастями в малых количествах. Похоже, что вы интегрируете промышленных роботов и строите специальные машины, а там часто нужны небольшие нестандартные детали, например держатели, распорки и крышки. Если вы сейчас заказываете что-то дорогое или долго ждёте, пришлите фото или короткое описание. Мы посмотрим и ответим конкретно.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Orbital','new','B','Дания','Skjern','sales@orbital.dk','https://orbital.dk/','','Датский производитель и ремонтник систем управления и электроники для старых ветротурбин (TMC3, IMC, Profibus).','{"rank": 38, "fit_score": 8, "why": "Выпускает и ремонтирует контроллеры и электронику, где нужны пластиковые корпуса, крышки, кронштейны и кабельные вводы для запчастей к старым турбинам. Реальные потребности в малых тиражах.", "give": "Мелкосерийные пластиковые корпусные детали, крышки, клипсы, кабельные вводы и кронштейны для контроллеров и шкафов управления.", "lang": "da", "subject_da": "Plastdele til styringer", "body_da": "Hej,\n\nJeg ser, at I bygger og reparerer styringer og elektronik til ældre vindmøller. Til den slags kan der være brug for små plastdele, fx dæksler og gennemføringer, som er svære at få i små antal. Det er den type, vi arbejder med, og vi tager gerne imod en enkelt del ad gangen. Send gerne et billede eller en kort beskrivelse, så ser vi, om vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для систем управления", "body_ru": "Здравствуйте,\n\nЯ вижу, что вы производите и ремонтируете системы управления и электронику для старых ветротурбин. Для этого могут понадобиться маленькие пластиковые детали, например крышки и кабельные вводы, которые трудно получить в малом количестве. Именно с такими деталями мы работаем, и нам подходит одна деталь за раз. Пришлите фото или короткое описание, и мы посмотрим, сможем ли решить задачу.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','PBN A/S','new','B','Дания','Videbæk','info@pbn-as.dk','https://pbn-as.dk','','Разработка, строительство и сервис специальных машин и систем автоматизации.','{"rank": 39, "fit_score": 8, "why": "Строят штучные машины и обслуживают их, так что им регулярно нужны индивидуальные пластиковые детали и запчасти для сервиса. Средняя компания, у которой есть служба сервиса.", "give": "Предложим быстрое изготовление пластиковых втулок, распорок, защитных крышек и направляющих для машин и сервиса.", "lang": "da", "subject_da": "Plastdele til maskiner og service", "body_da": "Hej,\n\nVi skaffer og får fremstillet små plastdele, fx bøsninger, afstandsstykker og dæksler, i få styk. Jeg bemærkede, at I både udvikler, bygger og servicerer specialmaskiner, så der kommer nok jævnligt en lille del, som ikke findes på hylden. Har I et billede eller en prøve, så send det gerne. Vi kigger på det og vender tilbage med et forslag, hvis vi kan løse det.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для машин и сервиса", "body_ru": "Здравствуйте,\n\nМы подбираем и заказываем небольшие пластиковые детали, например втулки, распорки и крышки, в малых количествах. Я заметил, что вы и разрабатываете, и строите, и обслуживаете специальные машины, поэтому у вас, наверное, регулярно возникает потребность в маленькой детали, которой нет в наличии. Если у вас есть фото или образец, пришлите. Мы посмотрим и вернёмся с предложением, если сможем это решить.\n\nС ув.\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Pehama Productions A/S','new','B','Дания','Nordborg','pehama@pehama.dk','https://www.pehama.dk','','Конструирование производственного оборудования, специальных машин и роботизированных решений.','{"rank": 40, "fit_score": 8, "why": "Строят уникальное оборудование для отдельных изделий, так что нужны разные пластиковые детали (направляющие, ограничители, крышки). Типичный заказчик для мелких партий.", "give": "Предложим пластиковые направляющие, ограничители, втулки и накладки для спецмашин в единичных и малых партиях.", "lang": "da", "subject_da": "Små plastdele til specialudstyr", "body_da": "Hej,\n\nJeg læste, at I konstruerer produktionsudstyr og specialmaskiner, bl.a. med robotter. Når hver maskine er lidt forskellig, er der ofte brug for små plastdele, som ikke fås færdige, fx føringer, anslag og afdækninger. Vi kan se på at lave dem i enkelte eksemplarer. Send os et billede eller en tegning, så får I et konkret svar, hvis det er noget, vi kan klare.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие пластиковые детали для спецоборудования", "body_ru": "Здравствуйте,\n\nЯ прочитал, что вы конструируете производственное оборудование и специальные машины, в том числе с роботами. Когда каждая машина немного отличается от другой, часто нужны маленькие пластиковые детали, которых нет в готовом виде, например направляющие, ограничители и накладки. Мы можем посмотреть, как сделать их в единичных экземплярах. Пришлите фото или чертёж, и вы получите конкретный ответ, если это то, с чем мы справимся.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Protek Marineservice ApS','new','B','Дания','Nyborg','mail@protekmarineservice.dk','https://www.protekmarineservice.dk','','Небольшой сервис и магазин морского оборудования и навигационной электроники для лодок в Нюборге.','{"rank": 41, "fit_score": 8, "why": "Малый сервис, монтирующий электронику и оборудование на лодки; часто нужны небольшие крепления, заглушки и накладки, которых нет у поставщиков.", "give": "Пластиковые кронштейны, накладки, заглушки и проставки по образцу в количестве от нескольких штук.", "lang": "da", "subject_da": "Små plastdele til bådudstyr", "body_da": "Hej,\nJeg forstår, at I sælger og monterer marineudstyr og navigationselektronik på både. Der er vel indimellem brug for et lille beslag, en afdækning eller en hætte, som leverandøren ikke har.\nDet er den slags, vi hjælper med at skaffe og få lavet i små mængder.\nHar I en opgave liggende, så send et billede eller et mål, så ser vi på det og vender tilbage med et forslag, hvis vi kan løse det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для лодочного оборудования", "body_ru": "Здравствуйте,\nКак я понимаю, вы продаёте и монтируете морское оборудование и навигационную электронику на лодки. Наверное, время от времени нужен небольшой кронштейн, накладка или колпачок, которого нет у поставщика.\nИменно такие детали мы помогаем найти и изготовить в небольших количествах.\nЕсли у вас есть такая задача, пришлите фото или размеры, мы посмотрим и вернёмся с предложением, если сможем это решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','RLAY A/S','new','B','Дания','Horsens','mail@rlay.dk','https://rlay.dk','','Производство электрощитов и шкафов управления для ветроэнергетики и промышленности, электромеханический сервис.','{"rank": 42, "fit_score": 8, "why": "В щитах много мелких пластиковых элементов: держатели кабеля, заглушки, проходки, дистанционные втулки, крышки, а стандартные детали часто не подходят. Среди клиентов Siemens Gamesa.", "give": "Изготовим нестандартные пластиковые кабельные проходки, заглушки, держатели и дистанционные детали для щитов малыми сериями.", "lang": "da", "subject_da": "Plastdele til eltavler og styreskabe", "body_da": "Hej,\nDa I bygger eltavler og styreskabe, går jeg ud fra, at I bruger mange små plastdele, fx kabelholdere, gennemføringer og afstandsbøsninger. Nogle gange passer standarddelene bare ikke.\nVi skaffer og får fremstillet den slags dele i små mængder.\nHar I en, der er svær at få fat i, må I gerne sende et billede eller en kort beskrivelse. Så kigger vi på den og giver et konkret svar.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для электрощитов и шкафов управления", "body_ru": "Здравствуйте,\nПоскольку вы делаете электрощиты и шкафы управления, я предполагаю, что вам нужно много мелких пластиковых деталей, например держатели кабеля, проходки и дистанционные втулки. Иногда стандартные детали просто не подходят.\nМы находим и изготавливаем такие детали в небольших количествах.\nЕсли какую-то деталь трудно достать, пришлите фото или краткое описание. Мы посмотрим и дадим конкретный ответ.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Robomatech','new','B','Дания','Brønderslev','info@robomatech.dk','https://robomatech.dk','','Профессиональные решения в области роботов и автоматизации.','{"rank": 43, "fit_score": 8, "why": "Небольшой интегратор роботов, который строит индивидуальные ячейки и использует много мелких пластиковых элементов (держатели, кожухи, прокладки). Нет собственного производства мелких деталей.", "give": "Сделаем кастомные пластиковые держатели, кожухи, кабельные вводы и заглушки для роботизированных ячеек.", "lang": "da", "subject_da": "Små dele til robotceller", "body_da": "Hej,\nJeg faldt over Robomatech, da jeg kiggede efter robot- og automationsfirmaer i Nordjylland. Når I bygger celler efter kundens behov, skal der vel ofte bruges små dele som holdere, afskærmninger og afstandsstykker, som ikke findes på hylden.\nVi hjælper med plastdele i små antal.\nHar I en bestemt del på tegnebrættet, så send os et billede eller en skitse, så vender vi tilbage, hvis vi kan hjælpe.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие детали для роботизированных ячеек", "body_ru": "Здравствуйте,\nЯ наткнулся на Robomatech, когда искал фирмы по роботам и автоматизации в Северной Ютландии. Когда вы строите ячейки под нужды клиента, вам, наверное, часто нужны небольшие детали вроде держателей, кожухов и дистанционных элементов, которых нет в продаже.\nМы помогаем с пластиковыми деталями в небольших количествах.\nЕсли у вас есть конкретная деталь в проекте, пришлите нам фото или эскиз, и мы вернёмся с ответом, если сможем помочь.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','SN Maskinservice','new','B','Дания','Rønnede','sn@snmaskinservice.dk','https://snmaskinservice.dk/maskinservice/','','Мобильный сервис и ремонт промышленного оборудования, включая пищевое, асфальтовое и пластиковое производство, по всей Зеландии.','{"rank": 44, "fit_score": 8, "why": "Ремонтируют производственные линии на выезде, где при поломках нужны мелкие пластиковые детали быстро и в малом количестве.", "give": "Быстрое изготовление пластиковых запчастей и кронштейнов по образцу для аварийных ремонтов на линиях.", "lang": "da", "subject_da": "Plastreservedele til jeres service", "body_da": "Hej,\nI kører ud og reparerer produktionsudstyr, bl.a. inden for fødevarer og plastproduktion, har jeg set. Når noget går i stykker ude hos kunden, er det jo ofte en lille plastdel, der mangler, og man har ikke brug for hundrede stykker.\nDet kan vi hjælpe med at finde eller få lavet, fx bøsninger, dæksler eller føringer.\nNæste gang I står med sådan en del, så tag et billede og send det til os.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые запчасти для вашего сервиса", "body_ru": "Здравствуйте,\nЯ видел, что вы выезжаете и ремонтируете производственное оборудование, в том числе в пищевой и пластиковой отраслях. Когда что-то ломается на месте у клиента, часто не хватает именно маленькой пластиковой детали, и сто штук при этом не нужно.\nМы можем помочь найти или изготовить такое, например втулки, крышки или направляющие.\nВ следующий раз, когда столкнётесь с такой деталью, сфотографируйте её и пришлите нам.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Technor ApS','new','B','Дания','Hobro','technor@technor.dk','https://www.technor.dk','','Производитель и сервис вентиляционных и вытяжных систем для промышленности, выпускает собственные автоматические заслонки.','{"rank": 45, "fit_score": 8, "why": "Выпускают собственные заслонки и поставляют комплектующие и запчасти для вентиляции, значит регулярно используют мелкие детали и корпусные элементы. Есть и собственное производство, и сервис с запчастями.", "give": "Изготовим пластиковые втулки, крышки, держатели и корпусные мелкие детали для заслонок и вентиляционных узлов малыми партиями.", "lang": "da", "subject_da": "Plastdele til ventilationsanlæg", "body_da": "Hej,\nJeg kan se, at I laver og servicerer ventilations- og udsugningsanlæg, og at I selv producerer automatiske spjæld. Der er sikkert nogle små plastdele i det, fx hætter, bøsninger eller dæksler, som er svære at få i små serier.\nVi skaffer og får fremstillet den slags dele til maskiner og udstyr.\nHvis I har en reservedel, der driller, kan I sende et billede eller en kort beskrivelse, så vender vi tilbage med et forslag.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для вентиляционных систем", "body_ru": "Здравствуйте,\nЯ вижу, что вы производите и обслуживаете вентиляционные и вытяжные системы, а также сами выпускаете автоматические заслонки. Наверняка там есть небольшие пластиковые детали, например колпачки, втулки или крышки, которые трудно заказать малыми сериями.\nМы находим и изготавливаем такие детали для машин и оборудования.\nЕсли у вас есть запчасть, с которой сложности, пришлите фото или краткое описание, и мы вернёмся с предложением.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Thybotech Industriservice ApS','new','B','Дания','Them','thorben@thybotech.dk','https://thybotech-industriservice.dk/maskinreparation.aspx','Thorben','Ремонт и обслуживание промышленного оборудования по всей Дании, собственное изготовление запчастей в мастерской в Земе.','{"rank": 46, "fit_score": 8, "why": "Прямо пишут, что делают запчасти для машин, которые трудно достать; пластиковые втулки, крышки и уплотнительные элементы могут дополнить их металлические запчасти.", "give": "Пластиковые запчасти и втулки по образцу для снятых с производства или дорогих деталей, штучно и малыми сериями.", "lang": "da", "subject_da": "Plastdele til jeres reservedele", "body_da": "Hej Thorben,\nJeg læste på jeres hjemmeside, at I fremstiller reservedele til maskiner, som det er svært at få fat i dele til. Måske kan vi være et supplement, når der indimellem er brug for plastdele, fx bøsninger, dæksler eller afstandsstykker.\nVi er en lille virksomhed, der skaffer og får lavet plastdele i små mængder.\nHar I en del, hvor metal ikke er det rigtige, så send gerne et billede, så ser vi på den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали к вашим запчастям", "body_ru": "Здравствуйте, Торбен,\nЯ прочитал на вашем сайте, что вы изготавливаете запчасти для машин, к которым трудно достать детали. Возможно, мы сможем быть дополнением, когда время от времени нужны пластиковые детали, например втулки, крышки или дистанционные элементы.\nМы небольшая фирма, которая находит и изготавливает пластиковые детали в небольших количествах.\nЕсли есть деталь, для которой металл не подходит, пришлите фото, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Trium (B. Christensens Maskinfabrik Eftf. ApS)','new','B','Дания','Silkeborg','post@trium.dk','https://www.trium.dk','','Малая машиностроительная фирма: производит, ремонтирует и обслуживает насосы, изготавливает запчасти на заказ.','{"rank": 47, "fit_score": 8, "why": "Сами заявляют, что специально изготавливают запчасти для старых насосов разных брендов и имеют 3D-проектировщика. Пластиковые мелкие детали и кожухи можно закупать у нас вместо собственного изготовления.", "give": "Сделаем по образцу или 3D-модели пластиковые мелкие детали (втулки, крышки, прокладки-проставки) малыми партиями как субподряд.", "lang": "da", "subject_da": "Plastdele til gamle pumper", "body_da": "Hej,\nJeg så, at I laver reservedele til ældre pumper, også af andre mærker. Til den slags opgaver er der vel nogle gange små plastdele, fx bøsninger, afdækninger eller afstandsstykker, som det ikke giver mening at lave selv.\nDem kan vi hjælpe med at skaffe i små mængder.\nSend os gerne et billede eller et gammelt eksemplar, hvis I har sådan en del liggende, så skriver vi tilbage, om vi kan løse den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых насосов", "body_ru": "Здравствуйте,\nЯ увидел, что вы делаете запчасти для старых насосов, в том числе других марок. Для таких задач, наверное, иногда нужны небольшие пластиковые детали, например втулки, накладки или дистанционные элементы, которые нет смысла делать самим.\nМы можем помочь найти их в небольших количествах.\nПришлите нам фото или старый образец, если у вас лежит такая деталь, и мы ответим, сможем ли её решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Vilea Ventilation','new','B','Дания','Rødovre','kontakt@vilea.dk','https://vilea.dk','','Установка и сервис вентиляционных систем с рекуперацией тепла для частных и коммерческих клиентов.','{"rank": 48, "fit_score": 8, "why": "Прямо пишут, что ищут оригинальные запчасти для снятых с производства моделей вентиляции. Пластиковые крышки, заглушки и держатели для старых установок трудно найти.", "give": "Сделаем копии пластиковых крышек, заглушек, держателей и распорок для устаревших вентиляционных установок.", "lang": "da", "subject_da": "Plastdele til ældre ventilationsanlæg", "body_da": "Hej,\nJeg har set, at I efterlyser reservedele til ventilationsanlæg, som ikke produceres længere. Det kan være svært, især med små plastdele som dæksler, hætter og holdere.\nVi er en lille virksomhed, der hjælper med at skaffe og få lavet den slags dele i små mængder. Vi kan ikke love, at det lykkes hver gang, men vi ser gerne på det.\nHar I en defekt del, så send et billede af den, så vender vi tilbage.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых вентиляционных систем", "body_ru": "Здравствуйте,\nЯ посмотрел, что вы ищете запчасти для вентиляционных систем, которые больше не выпускаются. Это бывает сложно, особенно с мелкими пластиковыми деталями вроде крышек, колпачков и держателей.\nМы небольшая фирма, которая помогает находить и изготавливать такие детали в небольших количествах. Мы не можем обещать, что получится каждый раз, но с удовольствием посмотрим.\nЕсли у вас есть неисправная деталь, пришлите её фото, и мы вернёмся с ответом.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Wind Cluster ApS','new','B','Дания','Silkeborg','info@windcluster.com','https://windcluster.com','Peter Nyegaard Jensen','Поставка датчиков, компонентов гидравлических питч-систем и запчастей для ветротурбин по всему миру.','{"rank": 49, "fit_score": 8, "why": "Небольшая торговая и инжиниринговая компания с широкой номенклатурой датчиков и компонентов, которой нужны корпуса, крышки и крепёж малыми партиями. Собирает комплекты с партнёрами и закупает мелкие детали.", "give": "Предложим пластиковые корпусные элементы, держатели датчиков, крышки и проставки по чертежу или образцу в малых тиражах.", "lang": "da", "subject_da": "Små plastdele til jeres komponenter", "body_da": "Hej Peter,\nJeg kan se, at Wind Cluster leverer sensorer, hydrauliske pitch-komponenter og reservedele til vindmøller. Når man samler sæt til kunder, skal der vel nogle gange bruges små ting som dæksler, hætter eller gennemføringer i mindre antal.\nDet er netop den slags, vi hjælper med at skaffe.\nHar I noget, hvor leverandørens minimumsmængde er for stor, så send gerne et billede eller en kort beskrivelse til mig.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для ваших компонентов", "body_ru": "Здравствуйте, Петер,\nЯ вижу, что Wind Cluster поставляет датчики, компоненты гидравлических питч-систем и запчасти для ветротурбин. Когда вы собираете комплекты для клиентов, наверное, иногда нужны мелочи вроде крышек, колпачков или проходок в небольшом количестве.\nИменно с этим мы и помогаем.\nЕсли у вас есть позиция, где минимальная партия поставщика слишком велика, пришлите мне фото или краткое описание.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','WindTech A/S','new','B','Дания','Herning','info@wind-tech.dk','https://wind-tech.dk/','','Датская компания: восстановление и ремонт гондол и основных компонентов ветротурбин 225 кВт - 3 МВт (Vestas, Bonus, NEG Micon и др.).','{"rank": 50, "fit_score": 8, "why": "Полностью восстанавливает гондолы старых турбин, где многие мелкие детали (крышки, кронштейны, втулки, клипсы) сняты с производства. Очень релевантный профиль для замены деталей малыми партиями.", "give": "Замена снятых с производства мелких пластиковых деталей (крышки, кронштейны, втулки, клипсы, проставки) для рефурбишмента гондол малыми партиями.", "lang": "da", "subject_da": "Plastdele til ældre vindmøller", "body_da": "Hej,\nDa I istandsætter nacelles og hovedkomponenter på ældre vindmøller, støder I nok på dele, der ikke bliver lavet mere. Det gælder måske især små ting som dæksler, beslag og bøsninger.\nVi skaffer og får fremstillet plastdele i små mængder, og vi ser gerne på, om vi kan lave en afløser.\nHar I en del, der mangler eller er gået i stykker, så send os et billede eller selve delen, så vender vi tilbage med et konkret forslag.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых ветротурбин", "body_ru": "Здравствуйте,\nПоскольку вы восстанавливаете гондолы и основные компоненты старых ветротурбин, вам, наверное, попадаются детали, которые больше не выпускаются. Возможно, это касается особенно мелочей вроде крышек, кронштейнов и втулок.\nМы находим и изготавливаем пластиковые детали в небольших количествах и охотно посмотрим, сможем ли сделать замену.\nЕсли у вас есть недостающая или сломанная деталь, пришлите нам фото или саму деталь, и мы вернёмся с конкретным предложением.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Brovig Maskiner ApS','new','B','Дания','Todsbøl (Aabenraa)','post@brovig.dk','https://www.brovig.dk','','Дилер сельхоз-, садово-парковой и строительной техники с мастерской и складом запчастей.','{"rank": 51, "fit_score": 7, "why": "Заказывают запчасти через Kramp, Granit и др.; для старой техники они «достают детали за день», значит, нестандартные пластиковые элементы - постоянная задача.", "give": "Пластиковые крышки, втулки, держатели и кабельные проходки, быстро и в штучных или малых количествах.", "lang": "da", "subject_da": "Plastdele til ældre maskiner", "body_da": "Hej,\nI har værksted og reservedelslager til landbrugs- og havemaskiner, kan jeg se. På ældre maskiner er der jo tit en lille plastdel, som ikke længere kan skaffes, fx en hætte eller et dæksel.\nVi hjælper med at skaffe og få lavet sådan noget i små mængder, når originalen ikke er en mulighed.\nKommer I ud for det, så send et billede eller et mål, så ser vi, om vi kan finde en løsning.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старой техники", "body_ru": "Здравствуйте,\nЯ вижу, что у вас есть мастерская и склад запчастей для сельскохозяйственной и садовой техники. На старой технике часто бывает маленькая пластиковая деталь, которую уже не достать, например колпачок или крышка.\nМы помогаем найти и изготовить такое в небольших количествах, когда оригинал недоступен.\nЕсли вы с этим сталкиваетесь, пришлите фото или размер, и мы посмотрим, можно ли найти решение.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','CK-Mt A/S','new','B','Дания','Sydals','ck@ck-mt.dk','https://ck-mt.dk/produkter/baandbaner/','Claus Kjestrup (CEO)','Производитель ленточных конвейеров и комплексных транспортных систем на заказ.','{"rank": 52, "fit_score": 7, "why": "Каждый конвейер индивидуален, поэтому нужны разные мелкие детали в малых количествах (кронштейны, направляющие, крышки). Небольшая компания, для которой дорогие минимальные партии неудобны.", "give": "Сделаем мелкие пластиковые кронштейны, направляющие, крышки и распорки для их конвейеров в количестве по потребности.", "lang": "da", "subject_da": "Små dele til transportbånd", "body_da": "Hej Claus,\nJeg så, at I bygger transportbånd og transportanlæg efter kundens ønsker. Når hvert anlæg er lidt forskelligt, er det nok også forskelligt, hvilke små dele der skal bruges, fx føringer, dæksler eller beslag, og så er store minimumsmængder besværlige.\nVi arbejder med plastdele i små mængder til maskiner og udstyr.\nHar I en tegning eller et billede af noget, I mangler, så send det gerne, så ser vi på det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие детали для конвейеров", "body_ru": "Здравствуйте, Клаус,\nЯ увидел, что вы строите ленточные конвейеры и транспортные системы по желанию клиента. Когда каждая система немного отличается, то, наверное, отличаются и мелкие детали, которые нужны, например направляющие, крышки или кронштейны, а большие минимальные партии неудобны.\nМы работаем с пластиковыми деталями в небольших количествах для машин и оборудования.\nЕсли у вас есть чертёж или фото того, чего не хватает, пришлите, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Danbake / Brdr. Larsen Teknik ApS','new','B','Дания','Lynge','info@danbake.dk','https://danbake.dk','','Производит стоечные хлебопекарные печи Danbake, расстоечные шкафы и плавильни для шоколада с 1986 года.','{"rank": 53, "fit_score": 7, "why": "Небольшой производитель с изделиями, которые эксплуатируются по всему миру: пластиковые заглушки, ручки, крышки и держатели нужны как запчасти.", "give": "Изготовим небольшие партии пластиковых ручек, заглушек, крышек и держателей для печей и шкафов.", "lang": "da", "subject_da": "Reservedele til bageriovne", "body_da": "Hej,\nDet ser ud til, at I har lavet Danbake rackovne og hæveskabe siden 1986. Mange af dem kører sikkert stadig rundt om i verden, og så er der behov for plastdele som hætter, håndtag og dæksler, også længe efter at ovnen er solgt.\nVi hjælper med at skaffe og få lavet den slags i små mængder.\nSend gerne et billede af en del, I har svært ved at få fat i, så kigger vi på den.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для хлебопекарных печей", "body_ru": "Здравствуйте,\nПохоже, что вы с 1986 года делаете стоечные печи Danbake и расстоечные шкафы. Многие из них, наверное, до сих пор работают по всему миру, и тогда нужны пластиковые детали вроде колпачков, ручек и крышек, в том числе спустя долгое время после продажи печи.\nМы помогаем находить и изготавливать такое в небольших количествах.\nПришлите фото детали, которую вам трудно достать, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Danmatic','new','B','Дания','Viborg','danmatic@danmatic.dk','https://www.danmatic.dk','','Разрабатывает и производит оборудование для автоматизации хлебопекарен: декор, лотки, линии.','{"rank": 54, "fit_score": 7, "why": "Серийное оборудование для хлебопечения с контактными пластиковыми элементами (направляющие, накладки); нужны запчасти для уже установленных машин.", "give": "Предложим пластиковые накладки, направляющие, втулки и прочие простые детали для их машин в малых количествах.", "lang": "da", "subject_da": "Plastdele til bageriautomatik", "body_da": "Hej,\nJeg har set, at I udvikler og bygger udstyr til automatisering i bagerier. Når maskinerne har været i drift i nogle år, skal der vel af og til bruges nye føringer eller afdækninger af plast, som ikke bare kan købes.\nDet ser vi gerne på. Vi skaffer og får fremstillet plastdele i små mængder.\nHar I en del, der skal erstattes, så send os et billede eller en kort beskrivelse.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для автоматики пекарен", "body_ru": "Здравствуйте,\nЯ видел, что вы разрабатываете и строите оборудование для автоматизации пекарен. Когда машины проработали несколько лет, наверное, время от времени нужны новые направляющие или накладки из пластика, которые просто так не купить.\nМы с удовольствием на это посмотрим. Мы находим и изготавливаем пластиковые детали в небольших количествах.\nЕсли у вас есть деталь, которую нужно заменить, пришлите нам фото или краткое описание.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','DK Ship Supply ApS','new','B','Дания','Fredericia','info@dkshipsupply.dk','https://dkshipsupply.dk','','Снабжение судов в порту: запчасти, расходники, канаты, электроника и провиант, работают круглосуточно.','{"rank": 55, "fit_score": 7, "why": "Быстро находят запчасти для судов и принимают заказы на специальные детали; небольшой пластиковый компонент может стать для них готовым решением, когда оригинал недоступен.", "give": "Изготовление нестандартных пластиковых мелких деталей по образцу как дополнительный источник для их заказов на спецзапчасти.", "lang": "da", "subject_da": "Plastdele til skibe", "body_da": "Hej,\nJeg bemærkede, at I leverer reservedele og forsyninger til skibe i havnen, og at I også tager imod ordrer på mere specielle dele. Hvis der en gang imellem er en lille plastdel, som originalleverandøren ikke kan levere, kan vi måske hjælpe, fx med en bøsning, en hætte eller et dæksel.\nVi er en lille virksomhed og arbejder med små mængder.\nHar I en sag, så send gerne et billede eller en beskrivelse, så vender vi tilbage, om vi kan løse den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для судов", "body_ru": "Здравствуйте,\nЯ заметил, что вы поставляете запчасти и снабжение для судов в порту и принимаете заказы на более специальные детали. Если иногда нужна маленькая пластиковая деталь, которую оригинальный поставщик не может дать, возможно, мы сможем помочь, например со втулкой, колпачком или крышкой.\nМы небольшая фирма и работаем с небольшими количествами.\nЕсли у вас есть такой случай, пришлите фото или описание, и мы ответим, сможем ли решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','EGATEC A/S','new','B','Дания','Odense','kontakt@egatec.dk','https://egatec.dk','','Производитель упаковочных, паллетизирующих машин и решений end-of-line с роботами и системами зрения.','{"rank": 56, "fit_score": 7, "why": "Выпускает упаковочные машины и линии, где много мелких пластиковых элементов (направляющие, упоры, колпачки). Нуждается в запчастях для собственных машин и для сервиса клиентов.", "give": "Поставим мелкие пластиковые направляющие, упоры, крышки и кронштейны для упаковочных линий в малых партиях.", "lang": "da", "subject_da": "Små dele til pakkemaskiner", "body_da": "Hej,\nDa I bygger pakke- og palleteringsmaskiner, er der formentlig mange små plastdele i maskinerne, fx føringer, anslag og hætter. Både til jeres egne maskiner og til service hos kunderne kan det være godt at kunne skaffe enkelte dele uden at bestille en hel serie.\nDet hjælper vi gerne med.\nEt billede eller en kort beskrivelse af delen er nok til at starte, så ser vi på det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие детали для упаковочных машин", "body_ru": "Здравствуйте,\nПоскольку вы строите упаковочные и паллетирующие машины, в них, вероятно, много мелких пластиковых деталей, например направляющих, упоров и колпачков. Как для ваших собственных машин, так и для сервиса у клиентов бывает удобно достать отдельные детали, не заказывая целую серию.\nС этим мы охотно помогаем.\nФото или краткого описания детали достаточно для начала, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Grumsen Equipment A/S','new','B','Дания','Esbjerg','grumsen@grumsen.dk','https://grumsen.dk','','Ремонт и обслуживание дизелей, гидравлических лебёдок, насосов и рулевых систем для судов и офшорных установок в порту Эсбьерг.','{"rank": 57, "fit_score": 7, "why": "Свыше 70 лет обслуживают лебёдки, насосы и рулевые устройства, где часто нужны снятые с производства мелкие детали; склад запчастей и срочные поставки.", "give": "Быстрое изготовление небольших серий пластиковых кронштейнов, втулок, крышек и направляющих для их оборудования и сервисных комплектов.", "lang": "da", "subject_da": "Plastdele til spil og pumper", "body_da": "Hej,\nI har serviceret spil, pumper og rorsystemer til skibe og offshore i over 70 år, har jeg set. På så gamle maskiner kan små dele som bøsninger og dæksler være svære at få fat i, når fabrikken ikke laver dem mere.\nVi skaffer og får fremstillet plastdele i små mængder, og vi ser gerne på en af jeres.\nSend et billede eller et gammelt eksemplar, så skriver vi tilbage.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для лебёдок и насосов", "body_ru": "Здравствуйте,\nЯ видел, что вы больше 70 лет обслуживаете лебёдки, насосы и рулевые системы для судов и офшора. На таких старых машинах мелкие детали вроде втулок и крышек бывает трудно достать, когда завод их больше не делает.\nМы находим и изготавливаем пластиковые детали в небольших количествах и охотно посмотрим на одну из ваших.\nПришлите фото или старый образец, и мы напишем в ответ.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Grønkjærs Maskinværksted I/S','new','B','Дания','Hurup Thy','info@gronkjaer-mv.dk','https://www.gronkjaer-mv.dk','','Мастерская, изготавливает специальное оборудование для бойни, в том числе пилы для рёбер.','{"rank": 58, "fit_score": 7, "why": "Маленькая мастерская, делающая индивидуальные машины для бойни, которым нужны мелкие пластиковые узлы и запчасти без больших партий.", "give": "Поставим пластиковые втулки, направляющие, защитные крышки и распорки в нужном количестве.", "lang": "da", "subject_da": "Plastdele til slagteriudstyr", "body_da": "Hej,\nJeg læste, at I bygger specialmaskiner til slagterier, bl.a. ribbenssave. Til maskiner, der kun bygges i et fåtal, er det vel ikke altid let at finde de rigtige små plastdele, fx føringer, bøsninger eller dæksler.\nDem kan vi hjælpe med at skaffe og få lavet i små antal.\nMangler I en del, så send et billede eller en skitse til os, så ser vi, hvad vi kan gøre.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для бойневого оборудования", "body_ru": "Здравствуйте,\nЯ прочитал, что вы строите специальные машины для бойни, в том числе пилы для рёбер. Для машин, которые делают в единичных экземплярах, наверное, не всегда легко найти подходящие мелкие пластиковые детали, например направляющие, втулки или крышки.\nМы можем помочь найти и изготовить их в небольших количествах.\nЕсли вам чего-то не хватает, пришлите фото или эскиз, и мы посмотрим, что можно сделать.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Helsinge Maskinforretning A/S','new','B','Дания','Helsinge','reservedele@helsingemaskinforretning.dk','https://www.helsingemaskinforretning.dk','','Дилер Massey Ferguson и сельхозтехники с магазином и складом более 25 000 позиций запчастей.','{"rank": 59, "fit_score": 7, "why": "Большой склад и сервис тракторов и сельхозтехники разных лет; для старых машин часто не хватает мелких пластиковых деталей (колпачки, крышки, клипсы, втулки).", "give": "Мелкие пластиковые детали для старых тракторов и навесных орудий, которых нет у оригинального поставщика.", "lang": "da", "subject_da": "Plastdele til ældre traktorer", "body_da": "Hej,\nI er Massey Ferguson-forhandler med et stort reservedelslager, kan jeg se. Alligevel er der vel nogle gange små plastdele til ældre maskiner, som ikke kan skaffes, fx hætter, dæksler eller clips.\nDet er sådan noget, vi hjælper med i små mængder. Vi lover ikke noget på forhånd, men vi kigger gerne på det.\nHar I en sag, så send et billede af delen.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых тракторов", "body_ru": "Здравствуйте,\nЯ вижу, что вы дилер Massey Ferguson с большим складом запчастей. Тем не менее, наверное, иногда для старой техники не найти мелкие пластиковые детали, например колпачки, крышки или клипсы.\nИменно с этим мы помогаем в небольших количествах. Заранее мы ничего не обещаем, но с удовольствием посмотрим.\nЕсли у вас есть такой случай, пришлите фото детали.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','HJTools ApS','new','B','Дания','Esbjerg','hj@hjtools.dk','https://hjtools.dk/','','Изготовление и ремонт инструмента и оснастки, промышленный сервис и монтаж в Эсбьерге.','{"rank": 60, "fit_score": 7, "why": "Инструментальная мастерская с техниками-наладчиками: при ремонте оснастки и оборудования постоянно нужны небольшие пластиковые вставки, втулки и прокладки.", "give": "Мелкие пластиковые детали для оснастки и оборудования (втулки, прокладки, крышки, фиксаторы) по чертежу, от 1 штуки.", "lang": "da", "subject_da": "Små plastdele til jeres værktøj", "body_da": "Hej,\nDa I både fremstiller og reparerer værktøj og udstyr, kommer der vel af og til brug for en lille plastindsats, en bøsning eller et afstandsstykke.\nDet kan vi hjælpe med at skaffe eller få lavet i små mængder. Vi er en lille virksomhed og tager gerne små opgaver.\nSkriv endelig til os med et billede, et mål eller en kort beskrivelse, så ser vi på det og vender tilbage.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для вашего инструмента", "body_ru": "Здравствуйте,\nПоскольку вы и изготавливаете, и ремонтируете инструмент и оснастку, вам, наверное, время от времени нужна маленькая пластиковая вставка, втулка или дистанционный элемент.\nМы можем помочь найти или изготовить это в небольших количествах. Мы небольшая фирма и охотно берёмся за небольшие задачи.\nНапишите нам с фото, размером или кратким описанием, и мы посмотрим и вернёмся с ответом.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','HSV Combi ApS (HSV Service)','new','B','Дания','Bjert','service@hsvcombi.dk','https://hsvcombi.dk','Allan Skov Blytækker','Проектирует технологические линии для молочной промышленности и оказывает сервис и поставку запчастей, в том числе для чужого оборудования.','{"rank": 61, "fit_score": 7, "why": "Сервис для молочных заводов, где нужны запчасти для старых установок других производителей: пластиковые детали часто сняты с производства или дороги.", "give": "Сделаем замену снятых с производства пластиковых деталей и мелких запчастей для сервисного отдела в малых партиях.", "lang": "da", "subject_da": "Plastdele til ældre anlæg", "body_da": "Hej Allan,\nJeg skriver, fordi I både servicerer og leverer reservedele til mejerianlæg, også til udstyr fra andre producenter. Vi skaffer og får fremstillet små plastdele som bøsninger, dæksler og clips i små mængder. Det kan være en hjælp, når en original del er udgået eller bare dyr at få hjem. Har I en sådan del, må I gerne sende et billede eller en prøve, så ser vi på, om vi kan løse den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых установок", "body_ru": "Здравствуйте, Allan,\nПишу вам, потому что вы занимаетесь сервисом и поставкой запчастей для молочных установок, в том числе для оборудования других производителей. Мы находим и изготавливаем небольшие пластиковые детали, такие как втулки, крышки и клипсы, в небольших количествах. Это может пригодиться, когда оригинальная деталь снята с производства или просто дорогая. Если у вас есть такая деталь, пришлите фото или образец, и мы посмотрим, сможем ли решить задачу.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Jens Lübeck Agro ApS','new','B','Дания','Hadsund','info@jenslubeck.dk','https://jenslubeck.dk','','Семейный импортёр сельхозмашин (Unia, Zocon, Celli и др.) с мастерской и складом запчастей.','{"rank": 62, "fit_score": 7, "why": "Импортируют европейские машины небольших брендов и сами держат склад запчастей; на длинных сроках поставок из Польши и Италии местный поставщик мелких пластиковых деталей может ускорить ремонт.", "give": "Пластиковые заглушки, втулки, крышки и направляющие к импортным орудиям, когда оригинал идёт неделями.", "lang": "da", "subject_da": "Plastdele til importerede maskiner", "body_da": "Hej,\nJeg så, at I importerer landbrugsmaskiner fra bl.a. Polen og Italien og selv har værksted. Vi skaffer og får lavet små plastdele og reservedele i små mængder, fx hætter, bøsninger, dæksler og styr til redskaber. Hvis en lille del tager lang tid at få hjem, kan det være, at vi kan hjælpe. Send et billede af delen eller en kort beskrivelse, så kigger vi på den og skriver tilbage.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для импортных машин", "body_ru": "Здравствуйте,\nЯ увидел, что вы импортируете сельхозмашины, в том числе из Польши и Италии, и у вас есть своя мастерская. Мы находим и изготавливаем небольшие пластиковые детали и запчасти в малых количествах, например колпачки, втулки, крышки и направляющие для орудий. Если какую-то мелкую деталь долго везти, возможно, мы сможем помочь. Пришлите фото детали или краткое описание, мы посмотрим и напишем вам.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','JTT Conveying A/S','new','B','Дания','Bredsten','info@jtt.dk','https://www.jtt.dk','','Производитель конвейеров, транспортных лент и компонентов для транспортных систем.','{"rank": 63, "fit_score": 7, "why": "Конвейеры и компоненты состоят из множества мелких деталей, часть которых делается из пластика (направляющие, торцевые крышки, ролики-втулки). Для нестандартных конвейеров нужны мелкосерийные пластиковые детали.", "give": "Изготовим пластиковые направляющие, торцевые заглушки, втулки и крепёжные элементы для конвейеров под размер заказчика.", "lang": "da", "subject_da": "Små plastdele til transportbånd", "body_da": "Hej,\nDa I producerer transportbånd og komponenter til transportsystemer, tænker jeg, at der indimellem er brug for små plastdele i få styk. Det kan være styr, endedæksler eller bøsninger til en lidt speciel løsning. Det hjælper vi gerne med at skaffe eller få lavet. Har I en opgave, er I velkomne til at sende et billede eller en tegning, så får I et konkret svar fra os, hvis vi kan løse den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для конвейеров", "body_ru": "Здравствуйте,\nПоскольку вы производите конвейерные ленты и компоненты для транспортных систем, думаю, что время от времени вам нужны небольшие пластиковые детали в единичных экземплярах. Это могут быть направляющие, торцевые крышки или втулки для не совсем стандартного решения. Мы с радостью поможем найти или изготовить такие детали. Если у вас есть задача, присылайте фото или чертёж, и мы дадим конкретный ответ, если сможем её решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','L.F. Vindteknik','new','B','Дания','Søllested','allan@lfvindteknik.dk','https://www.lfvindteknik.dk/','Allan','Датский независимый сервис и ремонт ветротурбин (Vestas, Bonus/Siemens, Micon, Nordtank), механика, гидравлика, электрика, ISO 9001.','{"rank": 64, "fit_score": 7, "why": "Выполняет механический, гидравлический и электрический ремонт старых турбин, где постоянно нужны мелкие расходные и крепёжные детали. Небольшая компания, которой выгодны малые партии и быстрые замены.", "give": "Небольшие партии пластиковых крышек, клипс, проставок, втулок и кабельных вводов для замены изношенных или снятых с производства деталей.", "lang": "da", "subject_da": "Reservedele til ældre vindmøller", "body_da": "Hej Allan,\nJeg forstår, at I servicerer og reparerer ældre vindmøller som Vestas, Bonus og Nordtank. Her er de små plastdele vel ikke altid til at finde længere. Vi skaffer og får fremstillet dæksler, clips, afstandsstykker og gennemføringer i små mængder. Har I en slidt eller udgået del, så send os gerne et billede eller selve delen, så ser vi på, om vi kan lave en erstatning.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для старых ветротурбин", "body_ru": "Здравствуйте, Allan,\nКак я понимаю, вы обслуживаете и ремонтируете старые ветротурбины, такие как Vestas, Bonus и Nordtank. Мелкие пластиковые детали к ним, наверное, не всегда можно найти. Мы находим и изготавливаем крышки, клипсы, проставки и кабельные вводы в небольших количествах. Если у вас есть изношенная или снятая с производства деталь, пришлите нам фото или саму деталь, и мы посмотрим, сможем ли сделать замену.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Lauritz Andersen & Co. A/S','new','B','Дания','Odense','ordre@lauritzandersen.dk','https://lauritzandersen.dk/','','Технический торговый дом: смазки, приводные ремни, подшипниковые узлы, шланги, резина и пластик для машиностроения.','{"rank": 65, "fit_score": 7, "why": "Уже продают раздел деталей из резины и пластика, обслуживают мастерские и заводы по всей Дании и могут пополнить ассортимент мелкими пластиковыми запчастями.", "give": "Поставка мелких пластиковых запчастей и нестандартных деталей малыми партиями для перепродажи их клиентам.", "lang": "da", "subject_da": "Plastdele i små mængder", "body_da": "Hej,\nVi er en lille ny virksomhed, der skaffer og får lavet små plastdele. Jeg kan se, at I sælger gummi- og plastdele til værksteder og industri ved siden af remme, lejer og slanger. Hvis en kunde spørger efter en bøsning, en hætte eller et beslag, som ikke findes som standard, kan vi måske hjælpe i mindre mængder. Send gerne et billede eller en kort beskrivelse af en konkret del, så vender vi tilbage med et forslag.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали в малых количествах", "body_ru": "Здравствуйте,\nМы небольшая новая компания, которая находит и изготавливает мелкие пластиковые детали. Я вижу, что вы продаёте резиновые и пластиковые детали мастерским и промышленности, а также ремни, подшипники и шланги. Если клиент спрашивает втулку, колпачок или кронштейн, которых нет в стандартном ассортименте, мы, возможно, сможем помочь в небольших количествах. Пришлите фото или краткое описание конкретной детали, и мы вернёмся с предложением.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Lund & Sørensen A/S (L&S Windpower)','new','B','Дания','Vejle','info@ls-windpower.com','https://ls-windpower.com','','Разработка и производство электрообогрева и резисторов для ветротурбин, специалисты по холодному климату.','{"rank": 66, "fit_score": 7, "why": "Производит обогреватели для гондол и лопастей, где нужны мелкие изоляционные и крепёжные пластиковые детали (держатели, крышки, изоляторы). Мелкие серии и индивидуальные решения — их обычная практика.", "give": "Изготовим термостойкие пластиковые держатели, изолирующие втулки, крышки и дистанционные детали для нагревательных узлов.", "lang": "da", "subject_da": "Små dele til jeres varmeløsninger", "body_da": "Hej,\nTil elvarme og modstande til vindmøller, også i koldt klima, kan der vel indimellem være brug for små holdere, bøsninger og dæksler i få styk. Vi skaffer og får fremstillet den slags plastdele i små mængder. Hvis I har en opgave, hvor delen skal kunne tåle varme, så send os et billede eller en kort beskrivelse, så ser vi på, om det er noget, vi kan klare.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие детали для ваших нагревателей", "body_ru": "Здравствуйте,\nДля электрообогрева и резисторов для ветротурбин, в том числе в холодном климате, время от времени, наверное, нужны небольшие держатели, втулки и крышки в единичных экземплярах. Мы находим и изготавливаем такие пластиковые детали в малых количествах. Если у вас есть задача, где деталь должна выдерживать нагрев, пришлите фото или краткое описание, и мы посмотрим, сможем ли справиться.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Maskinfabrikken Hillerslev A/S','new','B','Дания','Thisted','info@hillerslev.dk','https://hillerslev.dk','','Производит машины из нержавеющей стали для пищевой промышленности: рыба, птица, мясо, молочка.','{"rank": 67, "fit_score": 7, "why": "Заказное машиностроение с индивидуальными линиями — постоянно нужны небольшие пластиковые элементы (направляющие, накладки, заглушки, крепления).", "give": "Изготовим пластиковые направляющие, накладки, крышки и крепёжные детали под конкретный проект малой партией.", "lang": "da", "subject_da": "Små plastdele til jeres maskiner", "body_da": "Hej,\nVi hjælper virksomheder med små plastdele i mindre mængder. Jeg har set, at I bygger maskiner i rustfrit stål til fisk, fjerkræ og kød, og at hver linje ofte er lidt speciel. Til den slags kan der vel indimellem mangle styr, dæksler eller hætter, som ikke findes som standard. Send os et billede eller en kort beskrivelse af en konkret del, så ser vi på den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для ваших машин", "body_ru": "Здравствуйте,\nМы помогаем компаниям с небольшими пластиковыми деталями в малых количествах. Я посмотрел, что вы строите машины из нержавеющей стали для рыбы, птицы и мяса, и каждая линия часто немного особенная. Для таких линий, наверное, время от времени не хватает направляющих, крышек или колпачков, которых нет в стандартном виде. Пришлите нам фото или краткое описание конкретной детали, и мы посмотрим.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','PRONOR IndustriTeknik A/S','new','B','Дания','Aarhus (Brabrand)','kontakt@pronor.dk','https://pronor.dk/','','Сервис и ремонт промышленного оборудования (электродвигатели, насосы, редукторы, гидравлика) и поставка запчастей, мастерские в Ютландии, на Фюне и Зеландии.','{"rank": 68, "fit_score": 7, "why": "Обслуживают более 2500 клиентов и постоянно закупают запчасти и компоненты; нехватка и долгие сроки на мелкие пластиковые детали типичны для такого сервиса.", "give": "Быстрые мелкие пластиковые запчасти (крышки, втулки, кожухи, распорки) для их ремонтных и сервисных заказов.", "lang": "da", "subject_da": "Plastdele til reparationsopgaver", "body_da": "Hej,\nKort fortalt skaffer og får vi lavet små plastdele i få styk. Det ser ud til, at I reparerer og servicerer motorer, pumper og gearkasser og har værksteder i både Jylland, på Fyn og på Sjælland. Mangler der et dæksel, en bøsning eller en afstandsring på en reparation, kan vi måske hjælpe. Oplever I, at sådanne dele er dyre eller svære at få hjem, så send et billede af delen, så vender vi tilbage.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для ремонтных заказов", "body_ru": "Здравствуйте,\nЕсли коротко, мы находим и изготавливаем небольшие пластиковые детали в единичных экземплярах. Похоже, что вы ремонтируете и обслуживаете электродвигатели, насосы и редукторы и у вас есть мастерские в Ютландии, на Фюне и на Зеландии. Если при ремонте не хватает крышки, втулки или распорного кольца, возможно, мы сможем помочь. Если такие детали дорогие или их трудно достать, пришлите фото детали, и мы вернёмся с ответом.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','RH Pumper A/S','new','B','Дания','Slagelse','info@rhpumper.dk','https://rhpumper.dk','','Сервис и ремонт всех типов насосов и насосных станций с собственным складом запчастей.','{"rank": 69, "fit_score": 7, "why": "Обслуживают насосы разных брендов и держат склад запчастей; когда детали нет на складе, приходится ждать у поставщиков. Мелкие пластиковые детали и крышки можно быстро закрыть нашими малыми партиями.", "give": "Предложим быстрое изготовление небольших пластиковых запчастей и аксессуаров для насосов по образцу.", "lang": "da", "subject_da": "Små dele til pumper", "body_da": "Hej,\nDa I reparerer pumper og pumpestationer, kender I sikkert situationen, hvor en lille del ikke er at finde hos leverandøren. Vi skaffer og får fremstillet små plastdele, fx dæksler, bøsninger og hætter, i små mængder og efter en prøve. Er der en del, I mangler, må I gerne sende et billede eller selve prøven. Så kigger vi på den og skriver tilbage, hvis vi kan lave den.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие детали для насосов", "body_ru": "Здравствуйте,\nПоскольку вы ремонтируете насосы и насосные станции, вы наверняка знакомы с ситуацией, когда маленькой детали нет у поставщика. Мы находим и изготавливаем небольшие пластиковые детали, например крышки, втулки и колпачки, в малых количествах и по образцу. Если вам не хватает какой-то детали, пришлите фото или сам образец. Мы посмотрим и напишем вам, если сможем её сделать.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Samtek ApS','new','B','Дания','Rødovre','samtek@samtek.dk','https://www.samtek.dk/maskinvaerksted.aspx','','Механический цех и слесарная мастерская: сервис, ТО промышленных установок и изготовление валов и деталей.','{"rank": 70, "fit_score": 7, "why": "Мастерская сама делает детали для обслуживания установок, но токарка и фрезеровка по металлу не покрывают мелкие пластиковые компоненты, которые нужны на каждом сервисе.", "give": "Мелкие пластиковые детали для сервисных работ (втулки, прокладки, крышки, распорки) малыми партиями.", "lang": "da", "subject_da": "Plastdele til jeres værksted", "body_da": "Hej,\nJeg bemærkede, at I har maskinværksted og laver service og vedligehold af industrianlæg. Plastdele ligger vel lidt uden for det, I selv fremstiller. Vi skaffer og får lavet bøsninger, afstandsstykker, pakninger og dæksler i små mængder. Hvis I en dag mangler sådan en del, så send os et billede eller en kort beskrivelse, så ser vi på, om vi kan tage opgaven.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для вашей мастерской", "body_ru": "Здравствуйте,\nЯ заметил, что у вас есть механический цех и вы занимаетесь сервисом и обслуживанием промышленных установок. Пластиковые детали, наверное, немного вне того, что вы делаете сами. Мы находим и изготавливаем втулки, проставки, прокладки и крышки в малых количествах. Если вам однажды понадобится такая деталь, пришлите фото или краткое описание, и мы посмотрим, возьмёмся ли за задачу.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','SenArch','new','C','Дания','Kongens Lyngby','contact@senarch.net','https://senarch.net','','Датский стартап (DTU Science Park), делает солнечные автономные IoT-шлюзы LoRaWAN.','{"rank": 71, "fit_score": 7, "why": "Аппаратный стартап, которому нужны корпуса, кронштейны и крепёжные детали для шлюзов в малых количествах. Производить свои мелкие пластиковые детали в малых сериях им дорого.", "give": "Предложим малые партии пластиковых корпусных деталей, креплений, крышек и проставок для их устройств.", "lang": "da", "subject_da": "Plastdele i små serier", "body_da": "Hej,\nJeg faldt over SenArch og jeres solcelledrevne LoRaWAN-gateways. Når man bygger hardware i få eksemplarer, kan det være svært at få små plastdele hjem uden at bestille store mængder. Vi skaffer og får lavet beslag, dæksler, afstandsstykker og lignende i få styk. Har I en del, I mangler, så send et billede, en skitse eller en kort beskrivelse. Så siger vi til, om vi kan hjælpe.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали малыми сериями", "body_ru": "Здравствуйте,\nЯ наткнулся на SenArch и ваши LoRaWAN-шлюзы на солнечных батареях. Когда делаешь аппаратуру в небольшом количестве, трудно получить мелкие пластиковые детали, не заказывая большие партии. Мы находим и изготавливаем кронштейны, крышки, проставки и подобное в единичных экземплярах. Если вам не хватает какой-то детали, пришлите фото, эскиз или краткое описание. Мы скажем, сможем ли помочь.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','SR Pack A/S','new','C','Дания','Løsning','info@srpack.dk','https://srpack.dk','','Производитель упаковочных машин и транспортных систем для хлебопекарной промышленности.','{"rank": 72, "fit_score": 7, "why": "С 1978 года поставляют линии на хлебозаводы, поэтому у них много старых машин, к которым нужны пластиковые детали (направляющие, ролики-втулки, крышки). Запчасти от производителя часто дороги.", "give": "Изготовим пластиковые направляющие, втулки, заглушки и держатели для пищевых транспортёров и упаковочных машин.", "lang": "da", "subject_da": "Reservedele til pakkemaskiner", "body_da": "Hej,\nSiden 1978 har I leveret pakkemaskiner og transportsystemer til bagerier, så der er sikkert mange ældre maskiner derude. Her kan små plastdele som styr, bøsninger og dæksler være en tilbagevendende opgave. Vi kan hjælpe med at skaffe dem i små mængder, især hvis originaldelen er dyr. Send os gerne et billede eller en prøve, så kigger vi på det og vender tilbage med et forslag.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для упаковочных машин", "body_ru": "Здравствуйте,\nС 1978 года вы поставляете упаковочные машины и транспортные системы для пекарен, так что старых машин, наверное, много. Для них небольшие пластиковые детали, такие как направляющие, втулки и крышки, могут быть повторяющейся задачей. Мы можем помочь найти их в небольших количествах, особенно если оригинальная деталь дорогая. Пришлите фото или образец, мы посмотрим и вернёмся с предложением.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Storstrøms Vindkraft Vindmølleservice ApS','new','C','Дания','Sakskøbing','tm@stv-service.dk','http://www.stv-service.dk/','Thomas Melchior','Небольшая датская компания, которая устанавливает и обслуживает ветротурбины Nordtank, NEG-Micon, Bonus и Siemens на Зеландии и Лолланде-Фальстере.','{"rank": 73, "fit_score": 7, "why": "Обслуживает старые турбины, для которых оригинальные мелкие пластиковые детали (крышки, заглушки, держатели) часто сняты с производства или поставляются долго. Малый масштаб закупок идеально подходит для небольших партий.", "give": "Мелкосерийные замены пластиковых крышек, заглушек, втулок, кронштейнов и кабельных вводов для турбин Nordtank/NEG-Micon/Bonus по образцу или чертежу.", "lang": "da", "subject_da": "Små plastdele til vindmøller", "body_da": "Hej Thomas,\nNår man servicerer Nordtank-, NEG Micon- og Bonus-møller, er de originale små dele vel ikke altid lette at finde. Vi får lavet dæksler, propper, holdere, bøsninger og gennemføringer til kabler i små mængder efter en prøve eller en tegning. Har I en del, der mangler, så send et billede eller selve delen. Vi vender tilbage, hvis det er noget, vi kan løse.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для ветротурбин", "body_ru": "Здравствуйте, Thomas,\nКогда обслуживаешь турбины Nordtank, NEG Micon и Bonus, оригинальные мелкие детали, наверное, не всегда легко найти. Мы организуем изготовление крышек, заглушек, держателей, втулок и кабельных вводов в малых количествах по образцу или чертежу. Если у вас не хватает какой-то детали, пришлите фото или саму деталь. Мы вернёмся с ответом, если сможем это решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Svendborg Yacht Værft ApS','new','C','Дания','Svendborg','syv@syvas.dk','https://syvas.dk','','Семейная верфь, строящая специальные алюминиевые суда для офшора, ветроэнергетики и исследований.','{"rank": 74, "fit_score": 7, "why": "Строят уникальные суда малыми сериями, где стандартных мелких деталей часто нет и нужны индивидуальные пластиковые элементы.", "give": "Индивидуальные пластиковые накладки, втулки, держатели и крышки по чертежу в единичных и малых количествах.", "lang": "da", "subject_da": "Plastdele til jeres byggeprojekter", "body_da": "Hej,\nI bygger specialskibe i aluminium til offshore, vindenergi og forskning. Når man bygger få skibe af samme slags, findes de små dele ikke altid som standard. Vi skaffer og får fremstillet plastbøsninger, holdere, dæksler og beslag i enkelte styk efter en tegning eller en prøve. Fortæl os kort, hvad I mangler, og send gerne et billede, så vender vi tilbage, hvis vi kan løse det.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для ваших проектов", "body_ru": "Здравствуйте,\nВы строите специальные алюминиевые суда для офшора, ветроэнергетики и исследований. Когда строишь немного судов одного типа, мелкие детали не всегда бывают стандартными. Мы находим и изготавливаем пластиковые втулки, держатели, крышки и кронштейны в единичных экземплярах по чертежу или образцу. Расскажите коротко, чего вам не хватает, и пришлите фото, и мы вернёмся с ответом, если сможем это решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','SØBY A/S','new','C','Дания','Højslev','soby@soby.com','https://www.soby.com','','Семейный производитель оборудования для транспортировки, сушки и аэрации зерна.','{"rank": 75, "fit_score": 7, "why": "Выпускают и держат на складе запчасти для норий, шнеков, цепных конвейеров и вентиляторов; в таких машинах много мелких пластиковых и износных деталей, нужных в сезон срочно.", "give": "Износостойкие пластиковые направляющие, втулки, крышки и прокладки малыми партиями для запчастей конвейеров и вентиляторов.", "lang": "da", "subject_da": "Plastdele til jeres kornanlæg", "body_da": "Hej,\nJeg ser, at I laver udstyr til transport, tørring og lufting af korn, bl.a. elevatorer og snegle. I den slags maskiner er der mange små slidte dele, og dem kan vi måske hjælpe med: styr, bøsninger og dæksler i små mængder. Hvis der er en del, der driller, så tag et billede og send det til os, så ser vi, hvad vi kan gøre.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для зерновых установок", "body_ru": "Здравствуйте,\nЯ вижу, что вы делаете оборудование для транспортировки, сушки и аэрации зерна, в том числе нории и шнеки. В таких машинах много мелких изнашиваемых деталей, и с ними мы, возможно, сможем помочь: направляющие, втулки и крышки в малых количествах. Если какая-то деталь доставляет проблемы, сфотографируйте её и пришлите нам, и мы посмотрим, что можно сделать.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','TI Automation A/S','new','C','Дания','Skjern','tia@ti-automation.dk','https://www.ti-automation.dk','','Производство и сервис распределительных щитов и шкафов управления для ветряной отрасли, сельского хозяйства и промышленности.','{"rank": 76, "fit_score": 7, "why": "Строит индивидуальные щиты и специальное испытательное оборудование для ветряной отрасли, где часто нужны нестандартные мелкие пластиковые детали. Адрес для запросов предложений указан на сайте.", "give": "Сделаем нестандартные пластиковые крышки, держатели кабелей, втулки и проставки для щитов и тестового оборудования в малом количестве.", "lang": "da", "subject_da": "Plastdele til tavler og styreskabe", "body_da": "Hej,\nJeg læste, at I bygger og servicerer eltavler og styreskabe, bl.a. til vindbranchen og landbruget. Til den slags tavler kan der være brug for en speciel kabelholder, et dæksel eller en bøsning i få styk. Det kan vi hjælpe med at skaffe. Har I en konkret opgave, så send et billede eller en kort beskrivelse, så får I et forslag fra os, hvis vi kan løse den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для щитов и шкафов управления", "body_ru": "Здравствуйте,\nЯ прочитал, что вы строите и обслуживаете электрощиты и шкафы управления, в том числе для ветровой отрасли и сельского хозяйства. Для таких щитов может понадобиться особый кабельный держатель, крышка или втулка в единичных экземплярах. Мы можем помочь найти такие детали. Если у вас есть конкретная задача, пришлите фото или краткое описание, и вы получите от нас предложение, если мы сможем её решить.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Tricon A/S','new','C','Дания','Kolding','tricon@tricon.dk','https://www.tricon.dk','','Конструирование и производство электрощитов и систем управления для ветроэнергетики, судов и промышленности.','{"rank": 77, "fit_score": 7, "why": "Выпускает и малые, и большие серии щитов, в том числе для ветровой отрасли, и использует много мелких монтажных пластиковых деталей. Нужны гибкие поставщики мелких серий.", "give": "Поставим пластиковые держатели, крышки, заглушки и монтажные детали под конкретные щиты малыми партиями с быстрой поставкой.", "lang": "da", "subject_da": "Små dele til jeres tavler", "body_da": "Hej,\nVi hjælper virksomheder med små plastdele og reservedele i mindre mængder. Jeg forstår, at I konstruerer og bygger eltavler og styringer til vindkraft, skibe og industri. I den slags tavler bruges der mange små monteringsdele, fx holdere, hætter og dæksler. Hvis der er noget, I har svært ved at få hjem i få styk, så send os et billede, så ser vi, om vi kan hjælpe.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие детали для ваших щитов", "body_ru": "Здравствуйте,\nМы помогаем компаниям с небольшими пластиковыми деталями и запчастями в малых количествах. Как я понимаю, вы конструируете и строите электрощиты и системы управления для ветроэнергетики, судов и промышленности. В таких щитах используется много мелких монтажных деталей, например держатели, колпачки и крышки. Если что-то трудно получить в нескольких экземплярах, пришлите нам фото, и мы посмотрим, сможем ли помочь.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Vest-El A/S','new','C','Дания','Hvide Sande','info@vest-el.dk','https://www.vest-el.dk','','Электромонтаж и морская электроника (радары, эхолоты, автопилоты, датчики улова) в Хвиде-Санде и Тюборёне.','{"rank": 78, "fit_score": 7, "why": "Устанавливают и ремонтируют морскую электронику и датчики улова, где нужны корпуса, крышки, кабельные вводы и крепления малыми партиями.", "give": "Пластиковые кабельные вводы, крышки, кронштейны и корпуса мелких элементов для установки и ремонта электроники на судах.", "lang": "da", "subject_da": "Plastdele til marineelektronik", "body_da": "Hej,\nJeg kan se, at I installerer og reparerer elektronik til skibe, bl.a. radar, ekkolod og autopilot. Ved montage om bord er der ofte brug for små dele som gennemføringer til kabler, dæksler og små beslag. Vi skaffer og får dem lavet i små mængder. Har I en del, I ikke kan finde, så skriv til os med et billede eller en kort beskrivelse. Vi giver besked, om vi kan klare den.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для морской электроники", "body_ru": "Здравствуйте,\nЯ вижу, что вы устанавливаете и ремонтируете электронику для судов, в том числе радары, эхолоты и автопилоты. При монтаже на борту часто нужны небольшие детали, такие как кабельные вводы, крышки и небольшие кронштейны. Мы находим и изготавливаем их в малых количествах. Если вы не можете найти какую-то деталь, напишите нам и приложите фото или краткое описание. Мы сообщим, сможем ли справиться.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Viggo Hansen A/S','new','C','Дания','Odense','info@viggo-hansen.dk','https://viggo-hansen.dk/','','Машиностроительный и слесарный завод: технологическое оборудование, теплообменники, автоматизация, ремонт и сервис.','{"rank": 79, "fit_score": 7, "why": "Выпускают оборудование для пищевой отрасли и сервисируют его, где нужны мелкие пластиковые детали (направляющие, втулки, крышки) малыми партиями.", "give": "Пластиковые направляющие, втулки, крышки и кронштейны по чертежу для их оборудования и сервиса.", "lang": "da", "subject_da": "Plastdele til udstyr og service", "body_da": "Hej,\nJeg har set, at I bygger procesudstyr og varmevekslere og også laver service og reparation. Vi arbejder med små plastdele i små mængder, for eksempel styr, bøsninger og dæksler, som kan være dyre at få fra originalleverandøren. Er der en del, I gerne vil have set på, hører vi meget gerne fra jer. Et billede og et par ord om den er nok til at starte.\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для оборудования и сервиса", "body_ru": "Здравствуйте,\nЯ посмотрел, что вы строите технологическое оборудование и теплообменники, а также занимаетесь сервисом и ремонтом. Мы работаем с небольшими пластиковыми деталями в малых количествах, например направляющими, втулками и крышками, которые могут быть дорогими у оригинального поставщика. Если есть деталь, на которую вы хотели бы, чтобы мы посмотрели, мы будем рады услышать от вас. Для начала достаточно фото и пары слов о детали.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Bendix Tool Maskinfabrik','new','C','Дания','Svebølle','info@bendixtool.dk','https://bendixtool.dk/maskinfabrik/','','Машиностроительный субподрядчик: специальное изготовление деталей и компонентов для машин и установок, ЧПУ-обработка, CAD/CAM.','{"rank": 80, "fit_score": 6, "why": "Поставляют компоненты для машиностроителей, которым часто нужны пластиковые детали вместе с металлическими в одном комплекте.", "give": "Дополнение их металлических поставок пластиковыми деталями (кронштейны, втулки, крышки) малыми партиями.", "lang": "da", "subject_da": "Plastdele ved siden af metaldele", "body_da": "Hej,\nDet ser ud til, at I fremstiller specialdele og komponenter i metal til maskinbyggere, bl.a. med CNC-bearbejdning. Hvis jeres kunder indimellem også beder om plastdele som beslag, bøsninger eller dæksler, kan vi måske tage dem. Så slipper I for at lede efter en ekstra leverandør til de små opgaver. Fortæl os gerne, hvad det drejer sig om, og send et billede eller en tegning, så vender vi tilbage med et udspil.\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали рядом с металлическими", "body_ru": "Здравствуйте,\nПохоже, что вы изготавливаете специальные детали и компоненты из металла для машиностроителей, в том числе с ЧПУ-обработкой. Если ваши клиенты время от времени просят и пластиковые детали, такие как кронштейны, втулки или крышки, возможно, мы сможем взять их на себя. Тогда вам не придётся искать ещё одного поставщика для мелких задач. Расскажите, о чём идёт речь, и пришлите фото или чертёж, и мы вернёмся с предложением.\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','DESMI A/S','new','C','Дания','Nørresundby','desmi@desmi.com','https://www.desmi.dk','','Производитель и сервисная компания по насосам с крупным складом запчастей (более 110 000 артикулов).','{"rank": 81, "fit_score": 6, "why": "Огромная номенклатура запчастей и сервис насосов разных марок, включая старые модели. Мелкие пластиковые детали для снятых с производства насосов трудно достать малыми партиями.", "give": "Изготовим небольшие партии пластиковых втулок, крышек, фиксаторов и распорок по образцу или чертежу для старых моделей насосов.", "lang": "da", "subject_da": "Plastdele til ældre pumper", "body_da": "Hej,\n\nJeg bemærkede, at I servicerer pumper, også ældre modeller. Når en model er udgået, kan det være svært at finde de små plastdele, f.eks. bøsninger og dæksler.\n\nVi skaffer og får fremstillet mindre plastdele og reservedele i små mængder. Har I en del, der driller, må I gerne sende et billede eller selve delen. Så ser vi på den og vender tilbage med et forslag, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для старых насосов", "body_ru": "Здравствуйте,\n\nЯ заметил, что вы обслуживаете насосы, в том числе старые модели. Когда модель снята с производства, найти мелкие пластиковые детали, например втулки и крышки, бывает трудно.\n\nМы подбираем и изготавливаем небольшие пластиковые детали и запчасти в малых количествах. Если есть деталь, с которой возникают сложности, пришлите фото или саму деталь. Мы посмотрим и вернёмся с предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Duelco A/S','new','C','Дания','Aalborg','info@duelco.dk','https://duelco.com','Thomas Espensen (Sales & Product Manager, Wind & Renewables)','Поставки электрокомпонентов и кабельных решений (кабельные лотки, крепёж кабеля, проходки) для ветроэнергетики и промышленности.','{"rank": 82, "fit_score": 6, "why": "Специализированный раздел для ветроэнергетики с кабельным крепежом и проходками; клиентам часто нужны нестандартные мелкие пластиковые детали, которых нет в каталогах. Есть отдельный отдел закупок.", "give": "Изготовим нестандартные пластиковые кабельные держатели, проходки, заглушки и распорки по запросу клиентов Duelco малыми партиями.", "lang": "da", "subject_da": "Plastdele til kabelmontage", "body_da": "Hej Thomas,\n\nDa I leverer kabelløsninger til vindindustrien, støder I nok indimellem på en kunde, der skal bruge en gennemføring eller en kabelholder, som ikke findes i kataloget.\n\nDen slags arbejder vi med: mindre plastdele i små mængder efter en prøve eller en beskrivelse. Har I en aktuel sag, kan I sende et billede eller et par linjer om, hvad der skal bruges. Så kigger vi på den og svarer med et konkret forslag, hvis vi kan.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для монтажа кабеля", "body_ru": "Здравствуйте, Томас,\n\nПоскольку вы поставляете кабельные решения для ветроэнергетики, вам, наверное, время от времени попадается клиент, которому нужна проходка или кабельный держатель, которых нет в каталоге.\n\nИменно этим мы и занимаемся: небольшие пластиковые детали малыми партиями по образцу или описанию. Если есть актуальный случай, пришлите фото или пару строк о том, что нужно. Мы посмотрим и ответим конкретным предложением, если сможем.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Egtved Maskinforretning','new','C','Дания','Egtved','info@egtvedmaskinforretning.dk','https://egtvedmaskinforretning.dk','','Семейная машинная фирма с продажей сельхозтехники, мастерской и складом.','{"rank": 83, "fit_score": 6, "why": "Мастерская и склад, управляемые владельцами; для ремонта машин разных лет нужны быстрые мелкие запчасти, включая пластиковые.", "give": "Пластиковые крышки, втулки, держатели и клипсы по образцу в малых количествах, с быстрой поставкой.", "lang": "da", "subject_da": "Små plastdele til landbrugsmaskiner", "body_da": "Hej,\n\nI sælger landbrugsmaskiner og har eget værksted, så I har sikkert prøvet at stå med en lille plastdel, som ingen har. Typisk et dæksel, en bøsning eller en clips til en maskine, der ikke er helt ny.\n\nVi skaffer og får fremstillet den slags i små mængder. Skriv gerne en mail med et billede af delen, eller send selve delen, så ser vi på den. Kan vi løse den, får I et konkret forslag fra os.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для сельхозтехники", "body_ru": "Здравствуйте,\n\nВы продаёте сельскохозяйственную технику и у вас есть своя мастерская, так что вы наверняка сталкивались с ситуацией, когда нужна маленькая пластиковая деталь, а её ни у кого нет. Обычно это крышка, втулка или клипса для не самой новой машины.\n\nМы подбираем и изготавливаем такие детали в малых количествах. Напишите нам письмо с фото детали или пришлите саму деталь, и мы посмотрим. Если сможем её сделать, вы получите от нас конкретное предложение.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Electro Energy','new','C','Дания','Glostrup','info@electro-energy.dk','https://electro-energy.dk','','Торговля запчастями для масляных и газовых котлов и тепловых насосов для монтажников и сервисных техников.','{"rank": 84, "fit_score": 6, "why": "Широкий ассортимент запчастей к котлам и тепловым насосам, в том числе для старых моделей; небольшие пластиковые детали могут дополнить их ассортимент как альтернативные позиции. Подходят как реселлеру.", "give": "Предложим небольшие партии пластиковых запчастей и аксессуаров (крышки, держатели, заглушки) для их ассортимента.", "lang": "da", "subject_da": "Reservedele til kedler og varmepumper", "body_da": "Hej,\n\nJeg så, at I har reservedele til olie- og gaskedler og varmepumper, også til ældre modeller. Til de ældre kan det være de små plastdele, som dæksler og holdere, der mangler.\n\nVi arbejder med at skaffe og få fremstillet den slags i små mængder. Hvis der er en del, jeres kunder spørger efter og ikke kan finde, så send os gerne et billede. Vi ser på det og vender tilbage, hvis vi kan lave den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для котлов и тепловых насосов", "body_ru": "Здравствуйте,\n\nЯ увидел, что у вас есть запчасти для масляных и газовых котлов и тепловых насосов, в том числе для старых моделей. Для старых моделей порой не хватает именно мелких пластиковых деталей, например крышек и держателей.\n\nМы занимаемся тем, что подбираем и изготавливаем такие детали в малых количествах. Если есть деталь, о которой спрашивают ваши клиенты и которую не найти, пришлите нам фото. Мы посмотрим и вернёмся, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Faaborg Værft A/S','new','C','Дания','Faaborg','fv@faaborg-vaerft.dk','https://www.faaborg-vaerft.dk','','Верфь, строящая и ремонтирующая суда из композитов, алюминия и стали, известна электропаромами.','{"rank": 85, "fit_score": 6, "why": "Среднего размера верфь с новостройками и ремонтом, где при отделке и обслуживании нужны мелкие пластиковые кронштейны, крышки и крепления.", "give": "Малые партии пластиковых крышек, кронштейнов и монтажных деталей для оснащения и ремонта судов.", "lang": "da", "subject_da": "Plastdele til jeres værft", "body_da": "Hej,\n\nVi har set, at I bygger og reparerer både i komposit, aluminium og stål, bl.a. de elektriske færger. Ved udrustning og vedligehold er der sikkert småting i plast, som er besværlige at få hjem i små antal, f.eks. dæksler, beslag eller bøsninger.\n\nDet er dem, vi kan hjælpe med. Send et billede eller en kort beskrivelse af en del, så ser vi på den og kommer med et forslag, hvis vi kan løse det.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для вашей верфи", "body_ru": "Здравствуйте,\n\nМы видели, что вы строите и ремонтируете суда из композита, алюминия и стали, в том числе электрические паромы. При оснащении и обслуживании наверняка есть мелкие пластиковые детали, которые трудно заказать в небольшом количестве, например крышки, кронштейны или втулки.\n\nИменно с ними мы можем помочь. Пришлите фото или краткое описание детали, мы посмотрим и вернёмся с предложением, если сможем это решить.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Flexbelt A/S','new','C','Дания','Vejle','info@flexbelt.dk','https://flexbelt.dk','','Изготовление транспортных лент на заказ, приводные ремни и барабанные моторы.','{"rank": 86, "fit_score": 6, "why": "Сами режут, сваривают и перфорируют ленты, а в комплект часто нужны пластиковые направляющие и профили. Работают на скорость (30 % заказов за 24 часа), поэтому ценят быстрых поставщиков мелочей.", "give": "Предложим быстрые пластиковые аксессуары: направляющие, упоры, захваты и крышки для лент и транспортёров.", "lang": "da", "subject_da": "Plastdele til transportbånd", "body_da": "Hej,\n\nJeg læste, at I laver transportbånd efter mål og leverer drivremme og tromlemotorer. Til den slags er der ofte brug for småting i plast, f.eks. styr, anslag eller dæksler, som man kun skal bruge få af.\n\nVi får fremstillet mindre plastdele i små mængder. Mangler I sådan en del til en opgave, må I gerne sende et billede eller en kort beskrivelse. Så kigger vi på den og vender tilbage med et udspil, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для транспортных лент", "body_ru": "Здравствуйте,\n\nЯ прочитал, что вы изготавливаете транспортные ленты на заказ и поставляете приводные ремни и барабанные моторы. Для этого часто нужны мелкие пластиковые детали, например направляющие, упоры или крышки, которых требуется немного.\n\nМы изготавливаем небольшие пластиковые детали в малых количествах. Если для какой-то задачи не хватает такой детали, пришлите фото или краткое описание. Мы посмотрим и вернёмся с предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Genpack A/S','new','C','Дания','Farum','sales@genpack.com','https://www.genpack.com/','','Поставщик упаковочных машин, запайщиков пакетов и расходных материалов, с сервисом по всей Дании.','{"rank": 87, "fit_score": 6, "why": "Имеют склад запчастей и сервисных техников, обслуживают много старых машин десятками лет. Мелкие пластиковые детали устаревших моделей трудно найти.", "give": "Предложим копии пластиковых запчастей к упаковочным машинам: крышки, втулки, держатели и направляющие.", "lang": "da", "subject_da": "Reservedele til pakkemaskiner", "body_da": "Hej,\n\nGenpack servicerer pakkemaskiner og poseforseglere over hele landet, og nogle af maskinerne har været i drift i mange år. Til de ældste kan små plastdele som bøsninger, styr og dæksler være svære at få fat i.\n\nVi skaffer og får lavet sådanne dele i små mængder. Så hvis en bestemt del driller, kan I sende et billede eller selve delen. Vi ser på den og svarer, om vi kan finde en løsning.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для упаковочных машин", "body_ru": "Здравствуйте,\n\nGenpack обслуживает упаковочные машины и запайщики пакетов по всей стране, и некоторые из этих машин работают уже много лет. Для самых старых моделей мелкие пластиковые детали, такие как втулки, направляющие и крышки, бывает трудно достать.\n\nМы подбираем и изготавливаем такие детали в малых количествах. Так что если какая-то деталь вызывает проблемы, пришлите фото или саму деталь. Мы посмотрим и ответим, сможем ли найти решение.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Krogsgaards Maskinværksted ApS','new','C','Дания','Vejen','mail@dreje.dk','https://dreje.dk/','','Субподрядчик по ЧПУ-токарной и фрезерной обработке металла и пластика, специализация на единичных изделиях и малых сериях.','{"rank": 88, "fit_score": 6, "why": "Работают с единичными заказами и уже обрабатывают пластик, поэтому могут перепоручать или дополнять заказы мелкими пластиковыми деталями у партнёра.", "give": "Партнёрское производство мелких пластиковых деталей и серий, которые им невыгодно делать самим, чтобы они закрывали запросы клиентов целиком.", "lang": "da", "subject_da": "Små serier i plast", "body_da": "Hej,\n\nI drejer og fræser i både metal og plast, og mange af jeres opgaver er enkeltstykker eller små serier. Får I en forespørgsel, hvor en del af opgaven er en lille plastdel, som ikke passer ind hos jer, kan vi måske hjælpe. Vi skaffer og får fremstillet f.eks. bøsninger, afstandsstykker og dæksler.\n\nSend os gerne et billede eller en tegning, så kigger vi på den. Er det noget, vi kan klare, kommer vi med et konkret forslag.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие серии из пластика", "body_ru": "Здравствуйте,\n\nВы выполняете токарную и фрезерную обработку и металла, и пластика, и многие ваши заказы это единичные изделия или малые серии. Если приходит запрос, где часть работы это небольшая пластиковая деталь, которая вам не подходит по производству, мы, возможно, сможем помочь. Мы подбираем и изготавливаем, например, втулки, проставки и крышки.\n\nПришлите нам фото или чертёж, и мы посмотрим. Если это то, с чем мы справимся, сделаем конкретное предложение.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','KSN Industri A/S','new','C','Дания','Bjerringbro','ksn@ksn.dk','https://www.ksn.dk','','Производитель моечных установок, испытательных стендов и специальных машин.','{"rank": 89, "fit_score": 6, "why": "Строят нестандартные установки с трубной обвязкой и промышленными процессами, где много мелких пластиковых деталей (заглушки, кронштейны, колпаки). Нужны небольшие партии и быстрые сроки.", "give": "Изготовим пластиковые заглушки, колпаки, кронштейны и распорки для моечных и испытательных установок.", "lang": "da", "subject_da": "Plastdele til jeres anlæg", "body_da": "Hej,\n\nI bygger vaskeanlæg, teststande og specialmaskiner, og i den slags anlæg sidder der som regel en del småt plast, f.eks. propper, hætter og små beslag. Når I kun skal bruge nogle få stykker, kan det være træls at få dem hjem.\n\nDet kan vi hjælpe med. Vi skaffer og får fremstillet mindre plastdele i små mængder. Send gerne et billede eller en kort beskrivelse af, hvad I skal bruge, så vender vi tilbage med et konkret forslag, hvis vi kan.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для ваших установок", "body_ru": "Здравствуйте,\n\nВы строите моечные установки, испытательные стенды и специальные машины, а в таких установках обычно немало мелких пластиковых деталей, например заглушек, колпачков и небольших кронштейнов. Когда нужно всего несколько штук, достать их бывает неприятно сложно.\n\nС этим мы можем помочь. Мы подбираем и изготавливаем небольшие пластиковые детали в малых количествах. Пришлите фото или краткое описание того, что нужно, и мы вернёмся с конкретным предложением, если сможем.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','MEMAS (Mejlby Maskiner)','new','C','Дания','Nørager','torben@memas.dk','https://memas.dk','Torben Poulsen (butik og reservedele)','Небольшой дилер подержанной сельхозтехники с мастерской и магазином запчастей.','{"rank": 90, "fit_score": 6, "why": "Ремонтируют трактора, сеялки и комбайны разных марок и держат склад запчастей; для разнородной подержанной техники мелкие пластиковые детали часто дефицитны.", "give": "Мелкие пластиковые запчасти по образцу для ремонта разнородной сельхозтехники, без минимального заказа.", "lang": "da", "subject_da": "Plastdele til brugte maskiner", "body_da": "Hej Torben,\n\nJeg ved ikke, hvor ofte det sker hos jer, men når man reparerer brugte traktorer og såmaskiner af forskellige mærker, er der vel nogle gange en lille plastdel, der ikke findes mere. Et dæksel, en bøsning eller en clips.\n\nVi skaffer og får fremstillet sådanne dele i små mængder, også få stykker ad gangen. Har I en liggende, så send et billede eller selve delen, så ser vi på, om vi kan lave en magen til.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для б/у техники", "body_ru": "Здравствуйте, Торбен,\n\nНе знаю, как часто это бывает у вас, но когда ремонтируешь б/у тракторы и сеялки разных марок, наверное, иногда попадается маленькая пластиковая деталь, которой уже нет в продаже. Крышка, втулка или клипса.\n\nМы подбираем и изготавливаем такие детали в малых количествах, в том числе по несколько штук за раз. Если у вас такая лежит, пришлите фото или саму деталь, и мы посмотрим, сможем ли сделать такую же.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','NEK Værktøjsfabrik A/S','new','C','Дания','Billund','nek@nek.dk','https://www.nek.dk/kontakt/','','Проектирование, изготовление, сервис и ремонт пресс-форм для литья пластика, термоформинга и EPS в Биллунне.','{"rank": 91, "fit_score": 6, "why": "Сервис и ремонт форм требуют множества мелких вспомогательных деталей, а сотрудники хорошо понимают пластик и могут оценить качество наших деталей.", "give": "Мелкие пластиковые детали и вспомогательные элементы для форм, оснастки и сервисных работ малыми партиями с быстрой поставкой.", "lang": "da", "subject_da": "Små dele til forme og værktøj", "body_da": "Hej,\n\nI laver og servicerer forme til sprøjtestøbning, termoformning og EPS, så I kender plast bedre end de fleste. Ved service og reparation går der sikkert også småting til, f.eks. bøsninger, afstandsstykker og hætter, som man gerne vil have hjem i få eksemplarer.\n\nVi får fremstillet den slags i små mængder. Har I en del, der er besværlig at skaffe, så send os et billede eller en prøve. Vi vender tilbage, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Мелкие детали для пресс-форм и оснастки", "body_ru": "Здравствуйте,\n\nВы делаете и обслуживаете пресс-формы для литья пластика, термоформинга и EPS, так что пластик вы знаете лучше большинства. При обслуживании и ремонте наверняка уходят и мелочи, например втулки, проставки и колпачки, которые хочется получить в небольшом количестве.\n\nМы изготавливаем такие детали в малых количествах. Если есть деталь, которую сложно достать, пришлите нам фото или образец. Мы вернёмся, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Polytech A/S','new','C','Дания','Bramming','info@polytech.com','https://www.polytech.com','','Разработка и производство систем молниезащиты и датчиков молний (LKDS) для лопастей и ветротурбин.','{"rank": 92, "fit_score": 6, "why": "Выпускает электронику и крепёжные элементы внутри ступицы и лопасти, где нужны мелкие пластиковые корпуса, крышки и держатели. Есть собственная лаборатория и прототипирование.", "give": "Предложим мелкие пластиковые детали для прототипов и мелких серий: держатели, крышки, изолирующие втулки и кронштейны.", "lang": "da", "subject_da": "Små plastdele til prototyper", "body_da": "Hej,\n\nDa I udvikler lynbeskyttelse til vindmøllevinger, kan jeg forestille mig, at I indimellem skal bruge små plastdele til prototyper og mindre serier, f.eks. holdere, dæksler eller isolerende bøsninger.\n\nVi skaffer og får fremstillet den slags i små mængder. Har I en konkret del i tankerne, kan I sende et billede eller en kort beskrivelse, så ser vi på den og vender tilbage med et forslag, hvis vi kan hjælpe.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для прототипов", "body_ru": "Здравствуйте,\n\nПоскольку вы разрабатываете молниезащиту для лопастей ветротурбин, я могу себе представить, что вам время от времени нужны небольшие пластиковые детали для прототипов и малых серий, например держатели, крышки или изолирующие втулки.\n\nМы подбираем и изготавливаем такие детали в малых количествах. Если у вас есть конкретная деталь, пришлите фото или краткое описание, и мы посмотрим и вернёмся с предложением, если сможем помочь.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','PTI A/S','new','C','Дания','Tarm','mail@pti-as.dk','https://pti-as.dk','','Строит технологические установки, CIP и линии наполнения из нержавеющей стали для пищевой, фарм- и косметической промышленности.','{"rank": 93, "fit_score": 6, "why": "Собирает малые линии наполнения и упаковки с большим числом мелких комплектующих; нужны простые пластиковые детали и запчасти.", "give": "Предложим пластиковые направляющие, крышки, кронштейны и проставки для линий наполнения в малых количествах.", "lang": "da", "subject_da": "Plastdele til fyldelinjer", "body_da": "Hej,\n\nI bygger procesanlæg og fyldelinjer i rustfrit stål til fødevare- og medicinalindustrien. Så vidt jeg kan se, er der også mange små dele omkring sådan en linje, f.eks. styr, dæksler og afstandsstykker i plast.\n\nVi hjælper med at skaffe de dele i små mængder, når standarddele ikke passer. Send gerne et billede eller et par linjer om, hvad I mangler. Så ser vi på det og giver et konkret svar, hvis vi kan løse opgaven.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для линий розлива", "body_ru": "Здравствуйте,\n\nВы строите технологические установки и линии наполнения из нержавеющей стали для пищевой и фармацевтической промышленности. Насколько я вижу, вокруг такой линии много мелких деталей, например направляющих, крышек и проставок из пластика.\n\nМы помогаем подобрать такие детали в малых количествах, когда стандартные не подходят. Пришлите фото или пару строк о том, чего вам не хватает. Мы посмотрим и дадим конкретный ответ, если сможем решить задачу.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','SKOV A/S','new','C','Дания','Roslev (Glyngøre)','spareparts@skov.com','https://www.skov.com','','Производитель систем вентиляции и климат-контроля для свиноферм, птичников и молочных ферм.','{"rank": 94, "fit_score": 6, "why": "Большой выпуск вентиляционных блоков, заслонок и датчиков, у которых много мелких пластиковых деталей (крышки, кронштейны, втулки, заглушки); есть отдел запчастей, а старые серии трудно поддерживать.", "give": "Мелкие партии пластиковых запчастей к снятым с производства или редким узлам вентиляции: крышки, втулки, держатели, заглушки.", "lang": "da", "subject_da": "Reservedele til ventilation", "body_da": "Hej,\n\nJeg skriver til jer, fordi I laver ventilation og klimastyring til stalde. Med så mange ventilatorer, spjæld og følere er der sikkert en del små plastdele, f.eks. hætter, bøsninger og dæksler, som kan være svære at skaffe til de ældre serier.\n\nVi skaffer og får fremstillet den slags i små mængder. Hvis en del driller hos jer, må I gerne sende et billede eller en kort beskrivelse. Vi ser på den og vender tilbage med et udspil, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для вентиляции", "body_ru": "Здравствуйте,\n\nПишу вам, потому что вы производите вентиляцию и климат-контроль для животноводческих помещений. При таком количестве вентиляторов, заслонок и датчиков, наверное, есть немало мелких пластиковых деталей, например колпачков, втулок и крышек, которые бывает трудно достать для старых серий.\n\nМы подбираем и изготавливаем такие детали в малых количествах. Если какая-то деталь у вас вызывает проблемы, пришлите фото или краткое описание. Мы посмотрим и вернёмся с предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Sydfyns Båd & Byg','new','C','Дания','Vester Skerninge','mail@baadogbyg.dk','https://baadogbyg.dk','','Одноперсональная мастерская по ремонту и оснащению прогулочных лодок и небольших рабочих судов на Фюне.','{"rank": 95, "fit_score": 6, "why": "Очень маленькая мастерская, которой трудно быстро достать мелкие детали для монтажа и ремонта; закупает малые количества.", "give": "Быстрое изготовление нескольких пластиковых заглушек, накладок, втулок и креплений по образцу без больших минимальных партий.", "lang": "da", "subject_da": "Små plastdele til både", "body_da": "Hej,\n\nJeg forstår, at I reparerer og udruster lystbåde og mindre arbejdsbåde på Fyn. Når man kun skal bruge nogle få stykker, f.eks. en prop, en bøsning eller et lille beslag, er det ofte svært at få dem hjem.\n\nDet kan vi måske hjælpe med. Tag et billede af delen eller send selve prøven, så ser vi på den. Hvis vi kan lave den, får I et konkret forslag fra os.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Небольшие пластиковые детали для лодок", "body_ru": "Здравствуйте,\n\nКак я понимаю, вы ремонтируете и оснащаете прогулочные лодки и небольшие рабочие суда на Фюне. Когда нужно всего несколько штук, например заглушка, втулка или небольшой кронштейн, их часто трудно достать.\n\nС этим мы, возможно, сможем помочь. Сфотографируйте деталь или пришлите сам образец, и мы посмотрим. Если сможем её сделать, вы получите от нас конкретное предложение.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','SystemTeknik A/S','new','C','Дания','Nørresundby','info@systemteknik.dk','https://systemteknik.dk','Michael Mellergaard (CTO)','Производство силовых и управляющих электрощитов для ветропарков, солнечных и power-to-x проектов.','{"rank": 96, "fit_score": 6, "why": "Строит серии щитов для переходных элементов и подстанций, где используются многочисленные мелкие пластиковые детали и крепления. Есть производство в Дании и Польше, но для мелких нестандартных деталей нужны быстрые локальные поставщики.", "give": "Поставим нестандартные пластиковые проходки, держатели, заглушки и крышки для щитов малыми партиями.", "lang": "da", "subject_da": "Plastdele til eltavler", "body_da": "Hej Michael,\n\nI bygger el- og styretavler til vindparker og solenergi, og i tavler er der mange små ting i plast, f.eks. kabelgennemføringer, holdere og dæksler. Nogle gange skal man bruge en variant, der ikke findes som standard.\n\nVi får fremstillet sådanne dele i små mængder. Så hvis I har en del, der er svær at få hjem, send os et billede eller en kort beskrivelse. Vi kigger på den og vender tilbage med et konkret forslag, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для электрощитов", "body_ru": "Здравствуйте, Михаэль,\n\nВы строите силовые и управляющие щиты для ветропарков и солнечной энергетики, а в щитах много мелких пластиковых деталей, например кабельных проходок, держателей и крышек. Иногда нужен вариант, которого нет в стандартном исполнении.\n\nМы изготавливаем такие детали в малых количествах. Так что если есть деталь, которую трудно достать, пришлите нам фото или краткое описание. Мы посмотрим и вернёмся с конкретным предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Tor-Mo Trawl ApS','new','C','Дания','Hirtshals','info@tormotrawl.dk','https://hirtshalsservicegroup.dk/da/tor-mo-trawl-aps/','','Поставка и ремонт тралов, рыболовных снастей и судового оборудования, круглосуточный сервис в порту Хиртсхальс.','{"rank": 97, "fit_score": 6, "why": "Небольшая компания с широким ассортиментом судового и рыболовного оборудования и веб-магазином; мелкие пластиковые детали и аксессуары могут пополнить их ассортимент.", "give": "Поставка небольших партий пластиковых деталей и крепёжных элементов для перепродажи и срочных ремонтов на причале.", "lang": "da", "subject_da": "Plastdele til fiskeudstyr", "body_da": "Hej,\n\nI leverer og reparerer trawl og fiskeudstyr i Hirtshals. Hvis I indimellem mangler en lille plastdel til udstyr om bord, f.eks. en bøsning, en hætte eller et styr, kan vi måske hjælpe.\n\nVi skaffer og får fremstillet mindre plastdele i små mængder. Send gerne et billede eller selve delen, så ser vi på, om vi kan lave den. Kan vi det, vender vi tilbage med et konkret forslag.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для рыболовного оборудования", "body_ru": "Здравствуйте,\n\nВы поставляете и ремонтируете тралы и рыболовное оборудование в Хиртсхальсе. Если вам иногда не хватает маленькой пластиковой детали для оборудования на борту, например втулки, колпачка или направляющей, мы, возможно, сможем помочь.\n\nМы подбираем и изготавливаем небольшие пластиковые детали в малых количествах. Пришлите фото или саму деталь, и мы посмотрим, сможем ли её сделать. Если сможем, вернёмся с конкретным предложением.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','Vissenbjerg Maskinværksted ApS','new','C','Дания','Vissenbjerg','rh@vm-v.dk','https://vissenbjergmaskinvaerksted.dk/vi-udfoerer/cnc-drejning','','Небольшая механическая мастерская: ЧПУ-токарная и фрезерная обработка, стальные конструкции и ремонт под Оденсе.','{"rank": 98, "fit_score": 6, "why": "Небольшая мастерская с 45-летним опытом, которой для ремонта и изготовления конструкций регулярно нужны мелкие крепёжные и вспомогательные детали, в том числе из пластика.", "give": "Мелкие пластиковые детали (втулки, прокладки, крышки, фиксаторы) штучно или малыми партиями по образцу.", "lang": "da", "subject_da": "Plastdele i små antal", "body_da": "Hej,\n\nI drejer og fræser og laver stålkonstruktioner, og jeg forestiller mig, at der i reparationer og opgaver ofte skal bruges småting, som ikke lige findes på hylden. Hvis det er en plastdel, f.eks. en bøsning, et afstandsstykke eller et dæksel, kan vi måske hjælpe.\n\nVi skaffer og får fremstillet dem i små antal, også enkelte stykker. Send et billede eller en prøve, så ser vi på den og skriver tilbage.\n\nMvh\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали малыми партиями", "body_ru": "Здравствуйте,\n\nВы занимаетесь токарной и фрезерной обработкой и стальными конструкциями, и я представляю, что при ремонте и других заказах часто нужны мелочи, которых нет под рукой. Если это пластиковая деталь, например втулка, проставка или крышка, мы, возможно, сможем помочь.\n\nМы подбираем и изготавливаем такие детали в малых количествах, в том числе по несколько штук. Пришлите фото или образец, мы посмотрим и напишем вам в ответ.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','VMS Group A/S','new','C','Дания','Frederikshavn','vms@vms.dk','https://vms.dk','','Сервис, ремонт и запчасти для судовых двигателей, редукторов, винтов и турбокомпрессоров (Фредериксхавн, Скаген).','{"rank": 99, "fit_score": 6, "why": "Крупный сервис с мастерскими и собственным складом запчастей; регулярно нужны мелкие нестандартные детали для двигателей и вспомогательного оборудования, часто срочно.", "give": "Изготовление малых партий пластиковых втулок, крышек, заглушек, проставок и держателей под образец или чертёж для срочных ремонтов.", "lang": "da", "subject_da": "Plastdele til motorer og gear", "body_da": "Hej,\n\nVMS servicerer skibsmotorer, gear og turboladere, og en lille del er ikke altid nem at få hjem. Hvis det er en plastdel, f.eks. en bøsning, et dæksel eller et afstandsstykke, kan vi hjælpe med at skaffe eller få den fremstillet i små mængder.\n\nSend os gerne et billede eller selve delen. Så kigger vi på den og vender tilbage med et konkret forslag, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Пластиковые детали для двигателей и редукторов", "body_ru": "Здравствуйте,\n\nVMS обслуживает судовые двигатели, редукторы и турбокомпрессоры, а маленькую деталь не всегда легко достать. Если это пластиковая деталь, например втулка, крышка или проставка, мы можем помочь подобрать её или изготовить в малых количествах.\n\nПришлите нам фото или саму деталь. Мы посмотрим и вернёмся с конкретным предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('client','WEDA Danmark A/S','new','C','Дания','Randers NV','info@weda.dk','https://weda.dk','','Датское подразделение WEDA: кормовое оборудование, мельницы и оснащение свинарников.','{"rank": 100, "fit_score": 6, "why": "Продают и обслуживают системы жидкого кормления и оборудование стойл с давно эксплуатируемыми линиями (20+ лет), где запчасти от немецкого завода бывают долгими и дорогими.", "give": "Быстрое изготовление небольших партий пластиковых втулок, крышек и креплений для старых линий кормления.", "lang": "da", "subject_da": "Reservedele til foderanlæg", "body_da": "Hej,\n\nI sælger og servicerer væskefodringsanlæg og staldudstyr, og nogle af anlæggene har kørt i over 20 år. Så kan en reservedel fra producenten tage lang tid eller være dyr, især hvis det kun er en lille bøsning eller et dæksel i plast.\n\nDen slags kan vi måske lave i små mængder. Send gerne et billede eller en kort beskrivelse af delen, så vender vi tilbage med et udspil, hvis vi kan løse den.\n\nMed venlig hilsen\n[Dit navn]\nAV UniPlast\n[Telefon]", "subject_ru": "Запчасти для кормовых линий", "body_ru": "Здравствуйте,\n\nВы продаёте и обслуживаете системы жидкого кормления и оборудование для стойл, и некоторые линии работают уже более 20 лет. Тогда запчасть от производителя может идти долго или стоить дорого, особенно если это всего лишь маленькая пластиковая втулка или крышка.\n\nТакое мы, возможно, сможем сделать в малых количествах. Пришлите фото или краткое описание детали, и мы вернёмся с предложением, если сможем её сделать.\n\nС уважением\n[Имя]\nAV UniPlast\n[Телефон]"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Jysk Plast Industri ApS','new','A','Дания','Бекке (Южная Ютландия)','post@jyskplast.dk','https://www.jyskplast.dk/','','Обработка пластика и алюминия: 3-, 4-, 5-осевая фрезеровка, токарка, простые формы для литья, когда литьё выгоднее обработки. Делают новую деталь по эскизу от руки: могут измерить сломанную деталь на измерительной машине и нарисовать её в 3D (Creo). Повторные заказы дешевле: все программы сохранены.','{"why": "Лучшее совпадение с нашей идеей: у клиента лежит сломанная деталь, нужна такая же. Работают с одной детали, помогают с чертежом, быстро отвечают по-датски. Хороший первый партнёр.", "ask": "Цены датские, выше, чем в Польше или Прибалтике. Спросить, готовы ли работать с посредником. Не отдавать им контакты нашего клиента.", "minq": "от 1 шт. до 5000 шт.", "types": ["Обработка на станках ЧПУ", "Литьё под давлением"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Millit Plastbearbejdning ApS','new','A','Дания','Брёруп (Южная Ютландия)','rm@millit.dk','https://millit.dk/','','ЧПУ-фрезеровка (3 и 5 осей, станки DMG MORI) и токарка пластика, допуски до ±0,02 мм, обработка в помещении с контролем температуры. Делают запчасти для ветряков, пищевой, медицинской промышленности и машиностроения. Нужен PDF-чертёж, часто просят и 3D-файл. Умеют рисовать 2D и 3D.','{"why": "На сайте прямо написано, что делают запчасти для ветроэнергетики. Это наша первая целевая группа. Малая компания, подойдёт для штучных заказов.", "ask": "Присылать PDF-чертёж с размерами, количеством и допусками. Если у клиента только образец или фото, спросить про помощь с чертежом.", "minq": "от 1 шт. (штучные и серии)", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','JO Plast A/S','new','A','Дания','Стиллинг (Скандерборг)','joplast@joplast.dk','https://www.joplast.dk/branche/vindindustrien','','Технические пластиковые детали для ветряков по чертежам: вакуумная формовка (крышки, кожухи, щитки) и ЧПУ-фрезеровка (проставки, кронштейны, подшипники скольжения). Материалы PE1000, POM, PETP, PA-6, PC. Сертификат ISO 9001:2015, прослеживаемость.','{"why": "Один из немногих датских цехов, который сам указывает ветроэнергетику как отрасль и умеет делать и обработанные, и формованные детали. Для сервисных компаний по ветрякам это ровно их язык.", "ask": "Работают для крупных клиентов с документацией. Спросить минимальную сумму заказа и можно ли заказывать единичные детали.", "minq": "малые серии по чертежу заказчика", "types": ["Обработка на станках ЧПУ", "Термоформовка и листовой пластик"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','KKI Plast ApS','new','A','Дания','Колдинг','info@kkiplast.dk','https://kkiplast.dk/','','ЧПУ-фрезеровка (3, 4, 5 осей, в 2023 году добавили 5-осевой станок с роботом) и токарка пластика. PEHD500/1000/2000, PA, POM, PETP, PVC, PMMA, PP, PEEK, PUR, PVDF, PE, PETG, PC, PTFE. Подшипниковые корпуса, износные планки, детали для пищевых и транспортных линий, шнеки, ячейковые колёса, шестерни.','{"why": "Прямо работают с запчастями и малыми сериями для машиностроителей, офшора и пищевой отрасли. Дают советы, как сделать деталь дешевле.", "ask": "Не указан минимум: спросить письмом. Они уже обслуживают крупных клиентов, цена за штуку может быть выше польской.", "minq": "малые и средние серии, запчасти, прототипы", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','BN Plast Teknik ApS','new','A','Дания','Карисе (Зеландия)','info@bn-plastteknik.dk','https://www.bn-plastteknik.dk/vi-tilbyder/drejning.aspx','','ЧПУ-токарка пластика диаметром до Ø250 мм: два станка с подачей прутка до Ø80 мм и ручной станок. Делают детали по чертежам и STEP-файлам, советуют по материалу, дизайну и допускам.','{"why": "Небольшая мастерская на Зеландии. Для круглых деталей (втулки, проставки, ролики, оси) подходит отлично. Ближе к Копенгагену, удобно для срочных штучных заказов.", "ask": "Только токарка (и фрезеровка на станке с приводным инструментом). Для плоских и корпусных деталей лучше другой цех. Уточнить материалы.", "minq": "от 1 шт. (прототипы, штучные, серии)", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Holmegaard Plast','new','B','Дания','Недстведе (Зеландия)','hej@holmegaardplast.dk','https://holmegaardplast.dk/om-os/cnc-fraesning/','','ЧПУ-фрезеровка технического пластика и акрила, лазерная резка с полированными краями, раскрой листов на пилах. Работают по 3D-файлам и чертежам. Обслуживают промышленные компании по всей Зеландии.','{"why": "Подходит для листовых деталей: крышки, панели, прокладки, защитные кожухи. Хороший выбор на Зеландии.", "ask": "Больше про листовые детали. Для точёных деталей лучше другой цех. Спросить, берут ли единичные заказы.", "minq": "прототипы и серии, по запросу", "types": ["Обработка на станках ЧПУ", "Термоформовка и листовой пластик"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Create KBH','new','C','Дания','Копенгаген','contact@createkbh.dk','https://createkbh.dk/cncfraesning/','','ЧПУ-фрезеровка листового пластика: акрил, поликарбонат, HDPE, POM, ABS. Стол до 2500×1250 мм, типичная точность ±0,3 мм. Файлы DXF, DWG, STEP, IGES, PDF. Отвечают в течение 1 рабочего дня, срок обычно 3–10 рабочих дней.','{"why": "Быстрый вариант в Копенгагене для плоских деталей без жёстких допусков: накладки, шаблоны, пластины, прототипы.", "ask": "Допуск ±0,3 мм для точных деталей не подходит. Только 3-осевая фрезеровка.", "minq": "от 1 шт. (прототипы, отдельные детали)", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Acoplastic A/S','new','B','Дания','Эспергерде (Зеландия)','info@acoplastic.dk','https://acoplastic.dk/da/bearbejdede-plastloesninger/','','Обработка высокоэффективных пластиков на ЧПУ (фрезеровка, токарка, 5 осей): PTFE, PEEK, POM, PA, PSU, PEHD, PVC, PPS, PES, PVDF, PMMA, PC. Допуски до ±20 мкм, диаметр до 800 мм, шероховатость Ra 0,8.','{"why": "Подходят, когда нужна очень точная деталь из PTFE или PEEK: уплотнения, химическая и пищевая техника.", "ask": "Ориентированы на промышленные серии, для единичных деталей цена может быть высокой. Спросить минимальный заказ.", "minq": "от прототипа до больших серий", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Induflex A/S','new','B','Дания','Штёвринг (Северная Ютландия)','induflex@induflex.dk','https://www.induflex.dk/kompetencer/spaantagende-bearbejdning/','','ЧПУ-фрезеровка и токарка (3 и 5 осей) PA, PTFE, PETP, POM, PEEK, PVDF, PEHD. Допуск по умолчанию ISO 2768-1 medium. Типичный срок обработки около 14 рабочих дней. Одобрены Fødevarestyrelsen для материалов, контактирующих с пищей (EU 10/2011). Шнеки, шестерни, износные планки, втулки, подшипники.','{"why": "Для пищевых линий это сильный вариант: у них есть документы на пищевые материалы и прослеживаемость. Принимают DXF, STEP, PDF.", "ask": "Серийный цех. Срок 14 рабочих дней, это ориентир. Для единичных деталей уточнить цену.", "minq": "от 2 шт. до тысяч (по их сайту)", "types": ["Обработка на станках ЧПУ", "Термоформовка и листовой пластик"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Rolf Schmidt Industriplast A/S','new','B','Дания','Колдинг','rsip@rsip.com','https://rsip.com/en/','','Обработка термопластов на ЧПУ-центрах с роботами. 50 специалистов, 4000 м², сертификаты ISO 9001, ISO 14001, EcoVadis, на складе стандартные материалы. Продают также заготовки: плиты, прутки, профили.','{"why": "Крупный надёжный поставщик: и заготовки, и сложные детали, и серии. Подходит, когда заказ вырастет.", "ask": "Для небольших заказов может быть большой и неповоротливый. Спросить минимальную сумму.", "minq": "от одной детали до больших серий", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','LiqTech Plastics A/S','new','B','Дания','Хобро (Северная Ютландия)','salesplastics@liqtech.com','https://liqtechplastics.com/','','ЧПУ-обработка пластиков (PA, PE, POM, PETP, PP, PVDF, PPS, PEEK, PTFE, ABS, PC и другие), сварка пластика, гибка и склейка. Более 60 лет в отрасли. Сварные баки, трубы, кожухи и защитные экраны.','{"why": "Подходят, когда деталь не точёная, а сварная или гнутая: корпуса, ёмкости, кожухи.", "ask": "Больше про сварные и гнутые изделия. Для мелких точёных деталей лучше другой цех.", "minq": "малые и большие заказы", "types": ["Обработка на станках ЧПУ", "Термоформовка и листовой пластик"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Bovil ApS','new','B','Дания','Оденсе','bovil@bovil.dk','https://bovil.dk/','','ЧПУ-фрезеровка, токарка и техническая обработка пластмасс, автоматизация производства. Просят прислать запрос с чертежом.','{"why": "Ещё один исполнитель на Фюне для пластиковых деталей. Подходит как запасной.", "ask": "На сайте мало подробностей о минимальных партиях и материалах: уточнять письмом.", "minq": "по запросу", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','LV Teknik ApS','new','A','Дания','Виссенберг, около Оденсе','mail@lv-teknik.dk','https://www.lv-teknik.dk/','','ЧПУ-фрезеровка и токарка только алюминия и пластика, поэтому в деталях нет частиц других металлов. Работают для ветроэнергетики, пищевой и морской отрасли, упаковки. Есть роботизированные ячейки, работают круглосуточно. Клиенты в Дании и за границей.','{"why": "Явно берут и единичные детали, и серии. Среди клиентов указана ветроэнергетика. Цены, по их словам, невысокие («God kvalitet til billige priser»).", "ask": "Узнать, какие пластики в основном обрабатывают, и есть ли минимальная сумма заказа.", "minq": "от 1 шт. (штучные детали, прототипы, серии)", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Top CNC ApS','new','B','Дания','Оденсе','Top-cnc@mail.dk','https://www.top-cnc.dk/','','Машиностроительный цех, работает с 2001 года: ЧПУ-токарка и фрезеровка стали, нержавейки, алюминия, латуни и пластика (POM, PTFE и других). Отдельные детали по чертежу, пищевое производство, документированный контроль и прослеживаемость.','{"why": "Если клиенту нужен и пластиковый, и металлический вариант детали, они сделают оба.", "ask": "Больше про металл. Пластик указан как одно из направлений. Спросить, какие пластики в наличии.", "minq": "от 1 шт. (отдельные детали и серии)", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Rantec ApS','new','C','Дания','Свендборг','rantec@rantec.dk','https://www.rantec.dk/','','ЧПУ-обработка (фрезеровка, токарка, электроэрозия, 5 осей), изготовление инструмента и автоматизация. Детали из нержавейки и POM (кольца, заглушки, пищевые детали), алюминия и латуни. Заказы направлять на ordre@rantec.dk.','{"why": "Подходит для комбинированных деталей из POM и нержавейки, например для пищевых линий.", "ask": "Пластик у них не основное направление. Спросить, делают ли детали только из пластика.", "minq": "малые и большие серии", "types": ["Обработка на станках ЧПУ"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Nova Components','new','B','Дания','Рандерс','kontakt@novacomponents.dk','https://novacomponents.dk/','','Технические пластиковые детали по CAD-файлу, чертежу, образцу или описанию: обработка, термоформовка (колпаки, экраны, кожухи) и промышленная печать. Запчасти, оснастка, защитные кожухи, кронштейны, проставки.','{"why": "Сами пишут, что делают запчасти и штучные детали «по образцу». Три способа изготовления под одной крышей: можно подобрать подходящий для количества.", "ask": "Новая компания, данных о клиентах мало: проверить на небольшом заказе. Цены и сроки узнавать письмом.", "minq": "от 1 шт. (прототипы, запчасти, малые серии)", "types": ["Обработка на станках ЧПУ", "Термоформовка и листовой пластик"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','INKA-PLAST A/S','new','B','Дания','Оттеруп','inka@inkaplast.dk','https://inkaplast.dk/','','Литьё под давлением, 17 машин от 35 до 420 тонн, детали от нескольких граммов до примерно 1 кг, пластики, которые заменяют стальные кронштейны, обливка металлических деталей. Недорогие простые алюминиевые формы. Семейная компания с 1988 года.','{"why": "Для случая, когда клиенту нужно 100–1000 одинаковых деталей и деталь простая. Датский производитель, знает требования ЕС (в том числе к пищевому контакту).", "ask": "Цену формы и минимальную партию узнавать письмом. Для единичных деталей не подходит.", "minq": "малые производства на простых алюминиевых формах", "types": ["Литьё под давлением"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Idé-Pro A/S','new','B','Дания','Скиве','ide-pro@ide-pro.dk','https://www.ide-pro.dk/sproejtestoebning','','Литьё под давлением от 0,01 г до 41,5 кг, более 50 машин, собственный цех оснастки в Скиве. Прототипы на алюминиевой форме за 3–6 недель (быстрый вариант 1–3 недели), малые объёмы от 200 шт. в год. С 1997 года. Работают с PPS, PSU, PEEK, кроме PVC и силикона.','{"why": "Подходит, когда клиенту нужна малая серия (200–5000) одинаковых деталей и можно вложиться в алюминиевую форму. Сильный технический партнёр.", "ask": "Это уже проект, а не одна запчасть: форма, срок в неделях. Уточнить цену формы.", "minq": "малый объём от 200 шт. в год", "types": ["Литьё под давлением"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','CC Plast','new','B','Дания','Хиллерёд (Зеландия)','mail@ccplast.dk','https://ccplast.dk/producent-af-forme-til-sproejtestoebning/','','Свои алюминиевые формы для литья под давлением: срок формы от одной недели (по сайту). Собственный цех оснастки и литьё. Датская компания, ISO 9001. Технический директор и владелец Jes Nyhegn.','{"why": "Самый быстрый заявленный срок формы среди найденных. Подходит, когда клиент торопится с малой серией.", "ask": "«Одна неделя» это лучший случай: уточнить срок для нашей детали. Для единичных деталей не подходит.", "minq": "прототипы, нулевые и малые серии", "types": ["Литьё под давлением"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Davinci (Billund)','new','B','Дания','Биллунн (Южная Ютландия)','3dprint@davinci.dk','https://www.davinci.dk/services/injection-moulding-prototype/','','Литьё под давлением в алюминиевых формах для прототипов и малых серий, машины до 400 т, вес детали обычно до 1 кг. Типичный срок 3–6 недель. Принимают 3D CAD-файл с литейными уклонами, помогают проверить конструкцию.','{"why": "Хороший вариант, когда деталь нужна в настоящем материале и в нескольких десятках или сотнях экземпляров.", "ask": "Почта на сайте общая для технологических услуг. Нужен 3D-файл, подготовленный для литья: для старых деталей без модели сначала понадобится чертёж.", "minq": "прототипы и малые серии, по запросу", "types": ["Литьё под давлением"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','A. Johnsen Industri A/S','new','C','Дания','Фарум (Зеландия)','info@a-johnsen.dk','https://www.a-johnsen.dk/kompetencer/sprojtestobning-af-plast','','Литьё пластика под давлением с 1959 года, детали до 4600 г, собственный цех оснастки (ремонт и обслуживание форм), прототипы в алюминиевых и стальных формах, сборка.','{"why": "Один из самых опытных литейщиков Дании. Подходит, когда заказ вырастет до больших серий или нужны большие детали.", "ask": "Это серийный завод. Для малых партий уточнять минимальный объём.", "minq": "малые и большие серии", "types": ["Литьё под давлением"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Dansk Elastomer A/S','new','A','Дания','Аарупп','info@dansk-elastomer.dk','https://dansk-elastomer.dk/produkter/formstoebte-emner.aspx','','Литьё полиуретана (PUR): формы дешевле литьевых, делают оттиск с готовой детали и отливают такие же. Твёрдость от 55 до 98 Shore A и 58D, 72D. Литьё на металл, обливка колёс и валов, PUR-трубы, плиты, стержни. Работают с 1979 года, продают и за границу.','{"why": "Особенно подходят для запчастей из полиуретана или резины: если есть образец, они снимают с него форму и отливают копии. Дешевле, чем делать форму для литья под давлением.", "ask": "Материал полиуретан, а не PA или POM. Подходит не для всех деталей: уточнить, выдержит ли нагрузку и температуру.", "minq": "малые серии и специальные задачи", "types": ["Литьё полиуретана и отливки"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Nendan A/S','new','B','Дания','Нёрре Снеде','kontakt@nendan.dk','https://nendan.dk/','','Литьё полиуретановой резины (PUR) более 45 лет: валы, колёса, уплотнения, манжеты, снегоуборочные ножи, детали с несколькими составами. Своя мастерская форм, делают прототипы, могут отлить на детали заказчика и обновить отдельные детали. Совет по конструкции и материалу.','{"why": "Для сервисных деталей из полиуретана (катки, колёса, амортизаторы, уплотнения) и для восстановления изношенных деталей.", "ask": "Только полиуретан. Для жёстких конструкционных пластиков не подходит.", "minq": "штучно и серии, прототипы", "types": ["Литьё полиуретана и отливки"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','PUR-TEKNIK A/S','new','B','Дания','Бровст (Северная Ютландия)','purteknik@purteknik.dk','https://purteknik.dk/stoeberi/','','Литьё полиуретана с 1993 года: прототипы и готовые детали, массивные и вспененные отливки. Вес детали от нескольких граммов до более полутонны за одну отливку. Применяют только термореактивные материалы, затраты на форму ниже, чем при обычной форме.','{"why": "Хороший вариант для крупных полиуретановых деталей и для нестандартных заказов. Ещё один датский исполнитель для сравнения цены.", "ask": "Опять только полиуретан. Спросить минимальное количество и цену формы.", "minq": "от прототипов до готовых деталей", "types": ["Литьё полиуретана и отливки"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Prototal Denmark A/S','new','B','Дания','Таструп','3dp@prototal.dk','https://prototalgroup.com/dk/services/vakuumstoebning/','','Вакуумное литьё полиуретана и силикона в армированные силиконовые формы: ABS-подобные материалы, прозрачные, термостойкие смолы, резиноподобные от 10 до 85 Shore A. Первые детали через несколько дней, до 1000 деталей с одной формы. Толщина стенки не менее 1,5 мм.','{"why": "Подходит для партий 10–200 одинаковых деталей, которые не выгодно точить: корпуса, крышки, уплотнения, пылезащитные колпаки.", "ask": "Материалы «подобные» ABS или POM, не сами эти пластики. Спросить, подходит ли для нагрузки и износа.", "minq": "10–1000 шт. с одной формы", "types": ["Литьё полиуретана и отливки"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','EM-Fiberglas A/S','new','C','Дания','Хорнсюльд','emfiber@em-fiberglas.dk','https://em-fiberglas.dk/en/wind-industry/','','Детали из стеклопластика для ветроэнергетики, в том числе для морских ветряков: от небольших точных деталей до конструкций в несколько кубометров. Ручная выкладка, мокрое прессование, инфузия, RTM. Работают с ведущими производителями ветряков (OEM).','{"why": "Если клиенту из ветроэнергетики понадобится деталь из стеклопластика, а не из пластика: кожух, крышка, обтекатель.", "ask": "Работают с крупными OEM и сериями. Для единичных запчастей спросить, берут ли.", "minq": "малые и большие серии", "types": ["Стеклопластик и композиты"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','SP Tinby','new','C','Дания','Сёндерсё (Фюн)','info@sp-tinby.com','https://tinby.dk/om-komposit/','','Композитные детали для ветроэнергетики и гидроэнергетики: стекловолокно, углеволокно, эпоксидные и полиэфирные смолы. Формы и плуги, инфузия, RTM, ручная выкладка. Производство в Дании и США, корни компании с 1979 года.','{"why": "Запасной вариант для композитных деталей к ветрякам.", "ask": "Крупный поставщик для OEM. Для единичных запчастей спросить, берут ли.", "minq": "прототипы и серии", "types": ["Стеклопластик и композиты"], "lang": "da", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','МехаНова (ТОВ «МехаНова»)','new','A','Украина','Львовская область','cnc@mekhanova.com.ua','https://mekhanova.com.ua/','','Фрезерная обработка на ЧПУ (детали до 220×180×100 мм) и токарная обработка (до Ø80×100 мм). Алюминий и инженерные пластики: капролон PA6, POM, PTFE, PE-500, ABS. Принимают STEP, DXF, PDF и фото эскиза с размерами. Могут восстановить сломанную деталь по образцу или фото с размерами.','{"why": "Самое точное попадание в нашу тему: единичные пластиковые детали и мелкие партии без оснастки. Втулки, проставки, кронштейны, заглушки это ровно то, что чаще всего просят. Обещают расчёт и срок за один рабочий день.", "ask": "Работают по Украине (Новая почта). Спросить, отправляют ли за границу и как оформляют экспорт, как выставляют счёт на иностранную компанию. Крупные детали и сталь не делают.", "minq": "от 1 шт.", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Марабупласт (ТОВ «Марабу»)','new','A','Украина','Киев','info@marabuplast.com, marabuplast@gmail.com','https://marabuplast.com/en/','','Литьё пластика в силиконовые формы в вакууме: готовая деталь в нескольких экземплярах без металлической пресс-формы. Работают по чертежу, образцу или эскизу, делают копии деталей. Пишут, что работают с компаниями по всей Европе, 12 лет на рынке, более 25 000 изготовленных деталей.','{"why": "Подходит, когда нужно 5–200 одинаковых деталей, а обрабатывать их на станке дорого. Прямо указаны сервисные и ремонтные компании и «изношенные или поломанные детали» среди клиентов, то есть наша целевая группа.", "ask": "Материал литьевой (полиуретан и подобные), не всегда равен конструкционным PA или POM. Уточнить прочность, температуру, износ. Спросить про отправку за границу.", "minq": "от 1 до 1000 шт.", "types": ["Литьё в силиконовые формы"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Plast.Form','new','B','Украина','Украина','go.plastform@gmail.com','https://plastform.sitepulse.com.ua/','','Малосерийное литьё под давлением от 50 шт. Пресс-форма за 10 дней, деталь через неделю (по их сайту). Прямо пишут про запчасти малыми партиями и «запасной план» для производств.','{"why": "Для случая, когда клиенту нужно 50–500 одинаковых деталей, и литьё выгоднее обработки. Контактное лицо указано: Роман Гребень.", "ask": "Сайт похож на небольшой лендинг на платформе-конструкторе: нет юридических данных. Перед заказом проверить компанию (реестр, отзывы, пробный небольшой заказ). Сроки считать ориентировочными.", "minq": "от 50 шт. (литьё под давлением)", "types": ["Литьё под давлением"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','KLONA','new','B','Украина','Киев/Украина','hey@klona.ua','https://klona.ua/uk/uslugi/shtuchnyj-i-dribnoserijne-vyrobnycztvo','','Штучное и малосерийное производство пластиковых деталей, запчастей, корпусов. Для партий от 20 до 1000 шт. используют вакуумное литьё в силиконовые формы.','{"why": "Ещё один исполнитель на литьё малых партий, можно сравнить цену с Марабупласт.", "ask": "Для штучных деталей они используют другой способ, который нам не нужен. Работать только по литью от 20 шт. Материалы и сроки уточнять письмом.", "minq": "20–1000 шт. (литьё в силиконовые формы)", "types": ["Литьё в силиконовые формы"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Zeta Plus (ПП «Зета Плюс»)','new','B','Украина','Львов','office@zetaplus.com.ua','https://zetaplus.com.ua/en/company/services/plastic-products','','Литьё пластика под давлением на машинах от 5 до 600 тонн, собственное проектирование и изготовление пресс-форм, ABS, полистирол, полиамид, PP, PE. Работают с 2004 года.','{"why": "Подходит, когда клиент уже уходит от штучных деталей к регулярной серии: это полный цикл от пресс-формы до партии. Цены, по их словам, ниже европейских.", "ask": "Это серийное производство, под штучные заказы не рассчитано. Минимальную партию и стоимость формы узнавать письмом.", "minq": "серийно, детали до 1,5 кг", "types": ["Литьё под давлением"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Юрген (Juergen)','new','C','Украина','Харьков, Киев','info@juergen.ua','https://juergen.ua/ua/','','Изделия из акрила, монолитного поликарбоната, полистирола и технических пластиков (полиамид, поликарбонат, полиоксиметилен, полиэтилен, полипропилен). Вакуумная формовка и обработка на ЧПУ. Более 23 лет работают с машиностроительными и торговыми компаниями.','{"why": "Запасной вариант для листовых деталей: крышки, кожухи, защитные панели, прозрачные элементы.", "ask": "Больше про листовые и формованные изделия, чем про мелкие точёные детали. Харьков находится в зоне риска: возможны задержки.", "minq": "по запросу", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Сервис Юнион','new','C','Украина','Харьков, Киев','frezersunion@gmail.com','https://service-union.com.ua/mill_cnc_kaprolon','','Фрезеровка плоских деталей из листового капролона (полиамида) на ЧПУ: шайбы, втулки, кольца, прокладки, шестерни, крышки. Столы 550×400 мм и 1500×1500 мм, точность 0,1 мм. Расчёт по часам работы станка.','{"why": "Дешёвый вариант для плоских деталей: прокладки, шайбы, пластины, шестерни из листа.", "ask": "Точность 0,1 мм, объёмные точёные детали не делают. Только плоские. Харьков в зоне риска.", "minq": "от 1 шт., минимум 250 грн", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','MAJ-PLAST','new','A','Польша','Гданьск','majplast@majplast.com','https://majplast.pl/en','','Литьё пластика под давлением на машинах Engel 25–250 т, собственный инструментальный цех (пресс-формы), электроэрозионная обработка, ЧПУ-фрезеровка. Материалы PA, PP, ABS, PC, POM, PPS. Работают с 1993 года, сертификат ISO 9001, экспортируют в 12 стран ЕС, в том числе в Данию. Отвечают в течение 24 часов, прототипы за 5–10 дней (по сайту).','{"why": "Надёжный польский производитель с опытом экспорта в Данию. Делает как раз полиамидные шайбы, втулки и крепёжные детали. Хороший партнёр, когда клиенту нужно 50–500 одинаковых деталей из PA или POM.", "ask": "Для новой пресс-формы указывают 6–10 недель, для алюминиевой пробной формы от 3 недель. Спросить цену формы и минимум для штучных деталей без формы.", "minq": "пробные партии 50–500 шт., без жёсткого минимума", "types": ["Литьё под давлением", "Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','MIKRO','new','B','Польша','Ченстохова','biuro@mikroplastik.com.pl','https://mikroplastik.com.pl/en/','','Литьё под давлением на машинах Arburg: от микродеталей 0,05 г до 1000 г, собственный цех пресс-форм, измерительная машина Zeiss, ISO 9001. Экспортируют в Германию, Данию, США, Норвегию.','{"why": "Подходит для очень мелких пластиковых деталей (клипсы, фиксаторы, мелкие корпуса) в повторяющихся сериях, когда есть своя пресс-форма.", "ask": "Это серийное производство. Для штучных деталей не подходит. Спросить о минимальной партии и цене формы.", "minq": "серии (микролитьё от 0,05 г)", "types": ["Литьё под давлением"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','RIMET','new','A','Польша','Вышкув','biuro@rimet.pl','https://www.rimet.pl/','','Точная обработка на ЧПУ (фрезеровка и токарка) из алюминия, стали, латуни и инженерных пластиков, а также литьё пластика под давлением (ABS, PP, PA, PC). Измерительная машина, контроль качества. Принимают PDF и STEP. Уже экспортируют в Данию (данные государственной торговой платформы Польши trade.gov.pl от 14.10.2026).','{"why": "Один исполнитель для металла и пластика: если клиенту нужна деталь, которую можно сделать из пластика или из алюминия, предложат оба варианта. Опыт экспорта в Данию.", "ask": "Работают в основном для авиации, оборонки, автопрома: может быть высокий порог по сумме заказа. Спросить минимальную сумму заказа.", "minq": "от прототипа (1 шт.) до серий", "types": ["Обработка пластика на станках ЧПУ", "Литьё под давлением"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','3DForce','new','B','Польша','Щецин','','https://www.techpilot.com/en/profiles/3dforce-sp-z-oo','','Фрезерование на ЧПУ, изготовление пресс-форм и литьё пластика под давлением. Прототипы, штучные детали и партии. 20–50 сотрудников, сертификат ISO 9001, с 2016 года (данные профиля на Techpilot).','{"why": "Ещё один польский вариант с ЧПУ и литьём, подходит для сравнения цены.", "ask": "Прямой электронной почты на найденных страницах нет. Связаться через сайт или через профиль на Techpilot (контактное лицо Bartosz Skiba). Сертификат в профиле указан старой редакции, спросить актуальный.", "minq": "от 1 шт. (ЧПУ), литьё партиями", "types": ["Обработка пластика на станках ЧПУ", "Литьё под давлением"], "lang": "en", "form": "Профиль на Techpilot (кнопка Get in touch)"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','BilletWorks','new','A','Прибалтика','Рига, Латвия','info@billetworks.eu','https://www.billetworks.eu/services','','ЧПУ-обработка деталей до 800×500×500 мм, допуски до ±0,006 мм при серии, срок от 2 рабочих дней. Литьё пластика от 100 шт., детали до 230 г, срок от 2 недель. Сборка, ультразвуковая сварка, гравировка. Отвечают на запрос в течение 24 часов.','{"why": "Находятся в ЕС, быстро отвечают, берут единичные детали на станке и мелкие серии литья. Простая логистика до Дании без таможни.", "ask": "Не указано, с какими именно пластиками на станках они работают лучше всего. Спросить про PA6, POM, PE и PEEK.", "minq": "ЧПУ от 1 шт., литьё от 100 шт.", "types": ["Обработка пластика на станках ЧПУ", "Литьё под давлением"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Micromolds','new','A','Прибалтика','Вильнюс, Литва','info@micromolds.eu','https://www.micromolds.eu/low-volume-injection-molding','','Литьё мелких пластиковых деталей небольшими партиями от 100 до 10 000+ шт., детали до 100 мм и примерно до 20 см³, недорогая оснастка, срок 1–3 недели (по сайту). Сертификат ISO 13485, чистая комната. Собственный цех, доставка по Европе.','{"why": "Подходит, когда клиенту нужна малая серия мелких деталей без больших вложений в форму. Единственный из найденных, кто прямо специализируется на малых партиях литья от 100 шт.", "ask": "Подходят только детали небольшого размера. Для 1–20 штук не подходят: тогда лучше ЧПУ.", "minq": "от 100 шт.", "types": ["Литьё под давлением"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Vesimentor','new','B','Прибалтика','Эстония','info@vesimentor.ee','https://vesimentor.ee/en/services-productions','','Литьё под давлением, ротационное литьё, вакуумная формовка, ЧПУ для прототипов и малых серий, металлизация, ультразвуковая сварка, сборка. С 1997 года, сертификаты ISO 9001, ISO 14001.','{"why": "Подходит, если клиенту нужна деталь целиком: литьё, обработка, сборка, упаковка у одного исполнителя. Умеют переводить металлические детали на литой пластик.", "ask": "Ориентированы на серии. Минимальную партию и цену узнавать письмом: на сайте не указаны.", "minq": "по запросу (обычно серии)", "types": ["Литьё под давлением", "Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Plastprofiil','new','B','Прибалтика','Рийсипере, Эстония','info@plastprofiil.ee','https://www.plastprofiil.ee/en/services/cnc-milling-and-precision-machining/','','ЧПУ-фрезеровка пластика (ABS, PVC, PMMA, PC, PP, PS, PE, POM) и алюминия, точность до ±0,03 мм, срок обычно 5–10 рабочих дней. Помогают с чертежами, подбором материала, делают прототип перед серией. Рабочий стол до 2100×3000 мм.','{"why": "Подходит для больших и плоских пластиковых деталей и для единичных заказов с консультацией по материалу.", "ask": "Сайт ориентирован на заказчиков в Эстонии. Спросить об отправке в Данию и о счёте для иностранной компании.", "minq": "от 1 шт. (прототипы и малые серии)", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','PartRelay','new','B','Прибалтика','Литва, Латвия, Эстония, Финляндия','','https://www.partrelay.eu/','','Платформа: загружаете STEP-файл и сразу видите цену. Работу размещают у проверенных станочных цехов в Литве, Латвии, Эстонии и Финляндии. Обработка алюминия, стали, нержавейки и инженерных пластиков. Мгновенная цена до 600×600×600 мм и 100 шт.','{"why": "Быстрый способ узнать ориентир цены на обработку детали и проверить цены напрямую у цехов. Всё через одну компанию.", "ask": "Нужен STEP-файл (3D-модель). Если у клиента только фото или образец, придётся сначала делать модель. Цена платформы включает её наценку.", "minq": "от 1 шт., до 100 шт. в мгновенной цене", "types": ["Онлайн-платформа", "Обработка пластика на станках ЧПУ"], "lang": "en", "form": "Форма на сайте partrelay.eu"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','SERVISMONT s.r.o.','new','A','Чехия и Словакия','Яромерж-Йозефов, Чехия','plasty.sulc@email.cz','https://www.servismont.com/cnc-obrabeni','','ЧПУ-фрезеровка и токарная обработка технических пластиков: PA6, POM-C, PTFE, PEEK и другие, из склада в Йозефове. Точность ±0,02 мм, расчёт и срок в течение 24 часов. Принимают CAD (STEP, IGES) и PDF-чертёж. Втулки, подшипники скольжения, оси, уплотнения, фланцы.','{"why": "Прямой исполнитель для единичных запчастей из инженерных пластиков. Склад материала сокращает срок, быстрый расчёт, нет минимального заказа. Чехия: рядом, ЕС, без таможни.", "ask": "Данных об экспортном опыте нет. Спросить о счёте для датской компании (VAT) и условиях доставки.", "minq": "от 1 шт., без минимального количества", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','LABARA s.r.o.','new','B','Чехия и Словакия','Велька-Бітеш, Чехия','','https://www.labara.cz/en/production/machining/machined-parts-from-engineering-plastics','','ЧПУ-обработка деталей из инженерных пластиков по чертежам: PA, POM, PET, PBT, PC, PVDF, PE-UHMW, тефлон. Используют полуфабрикаты Röchling Engineering Plastics. Консультируют по материалу, допускам, делают прототипы.','{"why": "Хороший запасной исполнитель: использует материалы известного производителя инженерных пластиков, подходит для сервисных деталей в машиностроении, пищевой отрасли, сельском хозяйстве.", "ask": "Адрес почты на сайте скрыт защитой от спама. Позвонить или написать через форму на сайте.", "minq": "штучно, малые и средние серии", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": "Форма на сайте labara.cz"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','TechPlasty','new','B','Чехия и Словакия','Словакия','','https://www.techplasty.com/custom-made-products','','Запчасти и прототипы по чертежам или образцам, ЧПУ-обработка, резка и формирование, гибка листов, заливка полиуретана. Допуски по DIN ISO 2768 m.','{"why": "В описании прямо сказано про запчасти по образцу. Полиуретановая заливка даёт ещё один способ для малых партий.", "ask": "Прямой адрес почты не найден: связаться через форму «send us e-mail» на сайте.", "minq": "штучно и малые партии", "types": ["Обработка пластика на станках ЧПУ", "Литьё в силиконовые формы"], "lang": "en", "form": "Форма на сайте techplasty.com"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Metal One','new','B','Чехия и Словакия','Ладце, Словакия','info@metalone.eu','https://metalone.eu/en/materialy/plast','','Точная ЧПУ-обработка инженерных пластиков: POM-C, PEEK, PTFE, PA6, PET-G, PC. Допуски до ±0,01 мм, шероховатость Ra 0,8 мкм. Автоматические центры с подачей прутка для серий.','{"why": "Для деталей с высокими требованиями к точности: шестерни, подшипники скольжения, точные конструктивные детали. Подойдёт и для повторяющихся серий.", "ask": "Больше про автомобильную и авиационную отрасли. Спросить цену и минимальную сумму для небольшого заказа.", "minq": "от прототипа до серий в тысячи штук", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Werkia (SC Slovakia, s.r.o.)','new','B','Чехия и Словакия','Братислава, Словакия','','https://werkia.eu/en/cnc-machining','','ЧПУ-фрезеровка и токарная обработка металлов и пластиков (POM-C, PA6, PA66, PEEK, PTFE, PC, UHMWPE, PVDF) по чертежу. Расчёт в течение 48 часов, доставка в Германию, Австрию, Швейцарию, партнёры с сертификатом ISO 9001.','{"why": "Прямо работают для зарубежных заказчиков из ЕС и берут единичные запчасти. Есть сертификаты на материал по запросу.", "ask": "Заявлено, что доставляют в DE/AT/CH. Уточнить доставку в Данию. Сами производят «через партнёров»: узнать, кто именно делает деталь.", "minq": "от 1 шт.", "types": ["Обработка пластика на станках ЧПУ"], "lang": "en", "form": "Форма на сайте werkia.eu"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Protolabs Network (бывший Hubs)','new','B','Платформы','Европа и мир','','https://www.hubs.com/','','Онлайн-площадка: загружаете CAD-файл и сразу получаете цену. ЧПУ, литьё под давлением (цена на литьё за 48 часов), 3D-печать, листовой металл. Они берут на себя оформление таможни и пошлин при поставке в ЕС.','{"why": "Позволяет быстро получить ориентир цены и срока и заказать деталь без поиска цеха самим. Подходит, чтобы проверить, насколько наши цены конкурентны.", "ask": "Нужна 3D-модель. Цена включает наценку платформы, поэтому дороже, чем напрямую у цеха. Не стоит путать с поставщиком: исполнителя выбирает платформа.", "minq": "от 1 шт., без минимальной суммы", "types": ["Онлайн-платформа"], "lang": "en", "form": "Регистрация на hubs.com"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Xometry Europe','new','B','Платформы','Европа','','https://xometry.eu/en/home/','','Платформа с сетью более 5000 проверенных цехов в Европе, а также в Турции и Китае. Мгновенная цена на ЧПУ, вакуумное литьё и другие технологии, литьё под давлением. Корпоративный аккаунт даёт ручной расчёт по 2D-чертежам. Инженеры дают рекомендации по технологичности.','{"why": "Так же, как предыдущая: быстрый ориентир цены и запасной исполнитель, когда мы не нашли подходящий цех напрямую. Для нас важно: поддерживает корпоративные аккаунты и чертежи.", "ask": "Мгновенная цена только по 3D-файлам и в определённых пределах. Часть заказов может делаться в Турции или Китае: проверить страну производства до заказа.", "minq": "от 1 шт.", "types": ["Онлайн-платформа"], "lang": "en", "form": "Регистрация на xometry.eu"}'::jsonb);
insert into records (kind,name,status,priority,country,city,email,website,contact,summary,details) values ('executor','Techpilot','new','B','Платформы','Европа','service@techpilot.com','https://www.techpilot.com/','','Европейская платформа-каталог производственных компаний. Вы ищете поставщика по технологии и размеру партии и пишете ему напрямую. Профили показывают станки, материалы, размер партий.','{"why": "Источник новых исполнителей: можно искать цехи по странам и технологиям и добавлять в наш список. Здесь, например, нашёлся 3DForce.", "ask": "Это каталог, а не гарантия качества. Профили заполняют сами компании.", "minq": "каталог поставщиков", "types": ["Онлайн-платформа"], "lang": "en", "form": ""}'::jsonb);
insert into records (kind,name,status,website,summary,next_action) values ('site','Черновик сайта AV UniPlast','draft','https://tupter2003-sudo.github.io/100firm-k7x2/site/','Простой датский сайт с переключателем языка. Нет слов про 3D-печать, нет обещаний по срокам, наличию, сертификатам и ценам. Сайт закрыт от поисковиков.','Посмотреть вместе, поправить тексты, решить про домен.');
insert into records (kind,name,status,website,summary,next_action) values ('site','Домен и публичный запуск','idea','','Пока сайт только по секретной ссылке. Публиковать после согласия обоих и после того, как будут первые ответы от исполнителей.','Выбрать домен, например .dk, и решить, кто оплачивает.');
insert into records (kind,name,status,website,summary,next_action) values ('site','Свои фото деталей для сайта','idea','','Сейчас на сайте нарисованные и сгенерированные картинки. Заменить на свои фото, когда появятся первые образцы.','Сфотографировать первые детали.');
insert into records (kind,name,status,website,summary,next_action) values ('site','Форма заявки на сайте','idea','','Сейчас кнопка просто открывает письмо. Позже можно сделать форму с загрузкой фото детали.','');
